INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(456, 'plPL', 'Równowaga natury', 'Witaj, $N. Jestem konserwator Ilthalaine. Moim zadaniem w Cienistym Jarze jest dbać o to, by równowaga natury pozostała zachowana.$b$bTegoroczne wiosenne deszcze były wyjątkowo obfite, przez co jedne leśne zwierzęta się rozmnożyły, a inne ucierpiały.$b$bNiestety, nocnych szablobestii i ostowych dzików jest teraz zbyt wiele. Cienisty Jar nie wykarmi ich wszystkich. Wyrusz więc i przetrzeb dziki oraz szablobestie, aby harmonia natury została zachowana.', 'Zabij 4 młode nocne szablobestie i 4 młode ostowe dziki, a następnie wróć do konserwatora Ilthalaine\'a.', '', 'Wróć do konserwatora Ilthalaine\'a w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(457, 'plPL', 'Równowaga natury', 'Przetrzebienie młodych zwierząt tu, w Cienistym Jarze, było dobrym początkiem, $N, ale wciąż jest wiele do zrobienia.$b$bJeśli nie zaradzimy temu problemowi, zasoby lasu wyczerpią się zbyt szybko. Zabijanie zwierząt to zło konieczne dla dobra wszystkich, którzy dzielą tę ziemię. Wyrusz w głąb lasu i w imię równowagi zabij parszywe nocne szablobestie i ostowe dziki.', 'Konserwator Ilthalaine chce, żebyś $gzabił:zabiła; 5 parszywych nocnych szablobestii i 5 ostowych dzików.', '', 'Wróć do konserwatora Ilthalaine\'a w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(458, 'plPL', 'Opiekunka lasu', 'Całe szczęście, że jesteś, $N. Szepty leśnych duchów przyniosły mi dziwne wieści.$b$bTajemnicza opiekunka lasu, Tarindrella, powróciła do Cienistego Jaru. Od lat nie wyczuwano obecności tej driady w lasach Kalimdoru. Skoro wróciła do tej krainy, coś musi być nie tak.$b$bOdszukaj Tarindrellę i dowiedz się, co sprowadza ją do naszego gaju. Jedna ze Strażniczek widziała ją na południowy zachód od Aldrassilu.', 'Odszukaj driadę o imieniu Tarindrella.', '', '', '', '', '', '', 0),
(459, 'plPL', 'Opiekunka lasu', 'W lasach Teldrassilu budzi się coś złego. Rozejrzyj się po wzgórzach, na których dawniej żyły pokojowe furbolgi. Porzuciły swoje domy i gromadzą się teraz jako plemię Sękatej Sosny.$b$bTylko skażenie plugawego spaczonego mchu mogło wywołać taką przemianę. Grelle i grelliki opanowały okolicę i zagrażają mieszkańcom Cienistego Jaru.$b$bStań do walki z grellami i grellikami, $N, i sprawdź, czy rzeczywiście trzyma je w swej mocy urok plugawego spaczonego mchu.', 'Zbierz 8 kęp spaczonego mchu i przynieś je Tarindrelli.', '', 'Wróć do Tarindrelli w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(475, 'plPL', 'Niepokojący powiew', 'Przez las przechodzi niepokojący powiew.$b$bGaerolas Talvethren pełni funkcję Wielkiego Strażnika śpiących druidów Szponu w Kurhanie Ban\'ethil. Jako wybrany opiekun Śpiących ma dbać o ich bezpieczeństwo, by ich pakt z Yserą pozostał dochowany.$b$bWieści od Gaerolasa jednak się spóźniają i zaczynam się niepokoić. Udaj się na wschód do Wioski Gwiezdnej Bryzy i przynieś mi raport od Gaerolasa, abym mógł porzucić troski, wiedząc, że moi śniący bracia spoczywają bezpiecznie.', 'Odszukaj Gaerolasa Talvethrena w Wiosce Gwiezdnej Bryzy.$B', '', '', '', '', '', '', 0),
(476, 'plPL', 'Skażenie Sękatej Sosny', 'Plemię Sękatej Sosny zostało skażone!$b$bNiegdyś pokojowe furbolgi zwróciły się przeciwko obrońcom lasu. Napadły na mnie, gdy wyruszałem do Kurhanu Ban\'ethil, a potem splądrowały Wioskę Gwiezdnej Bryzy. Ursal Szarpacz, ich wódz, doprowadza je do szaleństwa złą mocą spaczonego mchu.$b$bJestem zbyt ciężko ranny, by zanieść Athridasowi te złe wieści. To zadanie spada na ciebie, $N. Oby tylko oszalałe furbolgi nie dotarły jeszcze do Ban\'ethil!', 'Wróć do Athridasa Niedźwiedziego Płaszcza w Dolanaar.', '', '', '', '', '', '', 0),
(483, 'plPL', 'Relikwie Przebudzenia', 'Widziano najeźdźców z Sękatej Sosny, którzy pustoszą Kurhan Ban\'ethil na zachodzie.$b$bJeśli im nie pomożemy, śpiący druidzi na wieki pozostaną uwięzieni w Szmaragdowym Śnie, nieświadomi swojego losu. Delikatnego rytuału hibernacji nie da się przerwać bez Relikwii Przebudzenia.$b$bUdaj się do kurhanu i odzyskaj Talizman Kruczego Szponu, Pióro Czarnego Pióra, Szafir Nieba i Runę Gniazda. Druidzi przechowują je w świętych skrzyniach. Przynieś je do mnie, a przygotuję rytuał przebudzenia.', 'Odzyskaj Relikwie Przebudzenia i przynieś je Athridasowi Niedźwiedziemu Płaszczowi w Dolanaar.', '', 'Wróć do Athridasa Niedźwiedziego Płaszcza na Teldrassilu.', '', '', '', '', 0),
(486, 'plPL', 'Ursal Szarpacz', 'Nadszedł czas, by ocalić druidów Szponu. Jeśli teraz zawiedziemy, $N, na zawsze pogrążą się we śnie.$b$bPrzygotuję Relikwie Przebudzenia i odprawię rytuał. Aby jednak moje dzieło przyniosło skutek, przeklęta bestia winna temu strasznemu położeniu musi zginąć. Dopiero wtedy rytuał się dopełni.$b$bTo Ursal Szarpacz wtrącił się w powołanie naszych braci i to Ursal Szarpacz musi teraz za to zapłacić, by mogli zostać uwolnieni. Udaj się do Warowni Sękatej Sosny na południowym zachodzie i zabij go.', 'Zabij Ursala Szarpacza i wróć do Athridasa Niedźwiedziego Płaszcza w Dolanaar.', '', 'Wróć do Athridasa Niedźwiedziego Płaszcza na Teldrassilu.', '', '', '', '', 0),
(487, 'plPL', 'Droga do Darnassus', 'Droga do Darnassus musi pozostać bezpieczna. Podróżni zmierzający z Dolanaar do Darnassus donoszą o bezlitosnych napaściach skażonych furbolgów z plemienia Sękatej Sosny.$b$bTą drogą codziennie płyną do Darnassus i z powrotem ważne wieści i towary. Nie możemy pozwolić, by zbójecka banda dzikusów terroryzowała podróżnych.$b$bChwyć za broń w imię świętego lasu, $N. Ich legowisko leży gdzieś poniżej tego punktu obserwacyjnego. Zabij 6 napastników Sękatej Sosny i zdaj mi raport.', 'Zabij 6 napastników Sękatej Sosny i wróć do strażniczki Amary Nocnej Wędrowniczki pod Dolanaar.', '', 'Wróć do kapłanki Księżyca Amary na Teldrassilu.', '', '', '', '', 0),
(488, 'plPL', 'Polecenia Zenna', 'Widzę, że palisz się do pracy. Masz szczęście – nie ma dnia, żebym nie marzył, by $gjakiś młody:jakaś młoda; $c spełniał moje polecenia.$b$bWidzisz, $N, mogę cię bardzo uszczęśliwić i dać ci rzeczy, o jakich nawet nie $gśniłeś:śniłaś;. Ale żeby tak się stało, musisz przynieść mi pewne przedmioty.$b$bMoje sprawy w lesie często wymagają pewnych... odczynników. Przynieś mi 3 kły nocnej szablobestii, 3 pióra puszczyka i 3 skrawki jedwabiu pająka z Pajęczego Lasu.$b$bNiech to zostanie naszą małą tajemnicą, dobrze?', 'Przynieś Zennowi Plugawemu Kopytu pod Dolanaar 3 kły nocnej szablobestii, 3 pióra puszczyka i 3 skrawki jedwabiu pająka z Pajęczego Lasu.', '', 'Wróć do Zenna Plugawego Kopyta na Teldrassilu.', '', '', '', '', 0),
(489, 'plPL', 'Szukaj odkupienia!', 'Rada Lasu wie, że $gpomogłeś:pomogłaś; Zennowi Plugawemu Kopytu. Ten satyr jest wrogiem lasu. Jako $r $gpowinieneś:powinnaś; wiedzieć, że nie wolno bezcześcić lasu, zabijając stworzenia Natury.$b$bJeśli chcesz pozostać $gprzyjacielem:przyjaciółką; Teldrassilu, musisz odkupić swe winy w oczach Rady.$b$bDaj Plugawemu Kopytu nauczkę, a dostąpisz odkupienia. Spaczone szyszki to skażone nasiona, które spadają z drzew. Bucha z nich zielony dym.$b$bDaj mu kilka. Pomyśli, że $gprzyniosłeś:przyniosłaś; mu niewinną przekąskę.', 'Zbierz 3 spaczone szyszki i daj je Zennowi Plugawemu Kopytu pod Dolanaar.', '', 'Wróć do Zenna Plugawego Kopyta na Teldrassilu.', '', '', '', '', 0),
(490, 'plPL', '', 'Na ścisły rozkaz Rady Darnassus ogłaszam nagrodę za plemię Sękatej Sosny. Nie są już przyjaciółmi lasu. Skażenie uczyniło z nich bezmyślne zagrożenie dla naszego ludu i stworzeń polany.$b$bZgodnie z postanowieniem Rady otrzymasz nagrodę za pozbycie się furbolgów z Kalimdoru. Przynieś mi ich kły jako dowód swoich czynów.', 'Shayla Nocna Bryza spod Darnassus chce, żebyś $gprzyniósł:przyniosła; jej 20 kłów Sękatej Sosny.', '', 'Wróć do strażniczki Shayli Nocnej Bryzy na Teldrassilu.', '', '', '', '', 0),
(916, 'plPL', 'Jad z Pajęczego Lasu', 'Przybyłem do Cienistego Jaru, by obserwować pająki z Pajęczego Lasu, które żyją w Jaskini Cienistej Nici. Są spokrewnione ze znacznie mniejszym gatunkiem pająków; sądzę, że drzewo świata wywarło na nie ogromny wpływ, i chciałbym zbadać okazy, by to potwierdzić.$B$BNajpierw chciałbym zdobyć trochę ich jadu. Zbierz gruczoły jadowe pająków z Pajęczego Lasu w Jaskini Cienistej Nici na północy i w jej okolicy. Będę mógł wtedy sprawdzić, czy ich jad przypomina jad mniejszych krewniaków.', 'Przynieś 10 gruczołów jadowych pająka z Pajęczego Lasu Gilshalanowi Wietrznemu Krokowi przy Aldrassilu.', '', 'Wróć do Gilshalana Wietrznego Kroku w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(917, 'plPL', 'Jajo z Pajęczego Lasu', 'Skoro mam już jad pająków, chciałbym zbadać żywe okazy. Niestety, schwytanie żywego olbrzymiego pająka to więcej, niż mogę od ciebie wymagać, $N. A i ja sam nie poradziłbym sobie z olbrzymim pająkiem!$B$BJeśli jednak znajdziesz niewyklute jajo, dostarczenie okazów będzie znacznie łatwiejsze, a ja zadbam o to, by młode pająki trzymano w zamknięciu.$B$BGdzieś w głębi Jaskini Cienistej Nici musi być gniazdo. Proszę, poszukaj w nim jaja i przynieś je do mnie.', 'Przynieś jajo z Pajęczego Lasu Gilshalanowi przy Aldrassilu.', '', 'Wróć do Gilshalana Wietrznego Kroku w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(918, 'plPL', 'Nasiona drzewczyków', 'Drzewczyki z Teldrassilu to żywiołaki natury. Pod pewnymi względami odzwierciedlają naturalny porządek roślin i zwierząt na naszym wielkim drzewie.$B$BDlatego niepokoi mnie, jak bardzo się rozgniewały.$B$BSądzę, że ma to coś wspólnego z glebą. Pracuję nad różnymi metodami pielęgnacji roślin i chciałbym wypróbować je na nasionach drzewczyków. Czy możesz zebrać nasiona drzewczyków z okolic Jeziora Al\'Ameth i przynieść mi je?', 'Przynieś 8 nasion drzewczyka Denalanowi nad Jeziorem Al\'Ameth.', '', 'Wróć do Denalana na Teldrassilu.', '', '', '', '', 0),
(919, 'plPL', 'Kiełki drzewczyków', 'Wokół wód Jeziora Al\'Ameth wyrastają małe drzewczyki. Obawiam się, że tym kiełkom nie da się już pomóc – powinniśmy usunąć je z tej ziemi, zanim urosną na tyle, by narobić kłopotów.$B$BJeśli podczas wędrówki wokół jeziora zobaczysz kiełki drzewczyków, zabierz je. Pomóż utrzymać naszą ziemię w czystości!', 'Przynieś 12 kiełków drzewczyka Denalanowi nad Jeziorem Al\'Ameth.', '', 'Wróć do Denalana na Teldrassilu.', '', '', '', '', 0),
(920, 'plPL', 'Wezwanie Tenarona', '$n, tak? Słyszałem, że Tenaron o ciebie pytał. Znajdziesz go w najwyższej komnacie na szczycie Aldrassilu.$b$bChoć żyjemy długo, lepiej nie każ mu zbyt długo czekać.', 'Porozmawiaj z Tenaronem Burzochwytem na szczycie Aldrassilu w Cienistym Jarze.', '', '', '', '', '', '', 0),
(921, 'plPL', 'Korona ziemi', 'Nadszedł czas, byś $gwyruszył:wyruszyła; na spotkanie swojego przeznaczenia, $n. Zanim jednak będziesz $ggotów:gotowa; ruszyć w świat poza naszymi zaczarowanymi lasami, musisz wiele się dowiedzieć o naszej niedawnej historii.$b$bOd bitwy o Górę Hyjal w życiu naszego ludu wiele się zmieniło. Nordrassil jest dziś ledwie bladym cieniem tego, czym był niegdyś – jego moc posłużyła do pokonania Archimonda i odparcia Płonącego Legionu...$b$bMusisz wykonać pewne zadanie. Idź do księżycowej studni na północ od Aldrassilu i przynieś mi fiolkę jej wody.', 'Napełnij kryształową fiolkę i przynieś ją Tenaronowi Burzochwytowi na szczyt Aldrassilu.', '', 'Wróć do Tenarona Burzochwyta w Cienistym Jarze na Teldrassilu.', '', '', '', '', 0),
(922, 'plPL', 'Rellian Zielona Iglica', '$N, czy możesz zanieść jedno z nasion, które mi $gprzyniosłeś:przyniosłaś;, mojemu przyjacielowi, Rellianowi Zielonej Iglicy? To druid z Darnassus, a gdy ostatnio rozmawialiśmy, wyznał, że interesuje się moją pracą nad drzewczykami. Sam ma kilka pomysłów i ucieszy się z nasienia, na którym będzie mógł pracować.$B$BDziękuję, $N. Bardzo mi $gpomogłeś:pomogłaś;. Mam nadzieję, że pewnego dnia zobaczysz owoce mojej pracy.$B$BRelliana zwykle znajdziesz na ścieżkach Enklawy Cenariona w Darnassus.', 'Przynieś nasiono drzewczyka Rellianowi Zielonej Iglicy w Darnassus.', '', '', '', '', '', '', 0),
(923, 'plPL', 'Guzy', 'W drzewczykach narasta coś złowrogiego. Staramy się znaleźć źródło, ale dopóki go nie znajdziemy... dla bezpieczeństwa Teldrassilu musimy ścinać drzewczyki, którym nie da się już pomóc. Najbardziej skażone są te, które krążą wokół Jeziora Źródlanego na północy Teldrassilu. Trzeba się ich pozbyć!$B$BZniszcz drzewczyki, które tam znajdziesz, i zbierz omszałe guzy, które na nich rosną. Przynieś mi te guzy, abym mógł je spalić.', 'Przynieś 5 omszałych guzów Rellianowi Zielonej Iglicy w Darnassus.', '', 'Wróć do Relliana Zielonej Iglicy na Tarasie Kupców w Darnassus.', '', '', '', '', 0),
(927, 'plPL', 'Serce oplecione mchem', 'Serce Czarnomecha Cuchnącego pokrywa ciemny, oleisty mech. W zasadzie tylko po powolnym, rytmicznym biciu można poznać, że to serce... Biciu, które trwa nadal.$B$BByć może Denalan zechce je zobaczyć.', 'Zanieś serce oplecione mchem Denalanowi nad Jeziorem Al\'Ameth.', '', '', '', '', '', '', 0),
(928, 'plPL', 'Korona ziemi', 'Choć mógłbym jeszcze wiele opowiedzieć ci o księżycowych studniach i o Teldrassilu, muszę cię wysłać dalej. Corithras Księżycowy Gniew będzie na ciebie czekał. Wodę z fiolki, którą mi $gprzyniosłeś:przyniosłaś;, przelałem do tego naczynia – zanieś mu je.$b$bOdszukaj Corithrasa. Znajdziesz go przy księżycowej studni w Dolanaar. Idź drogą na południe od Aldrassilu, wyjdź z Cienistego Jaru i trzymaj się bruku, gdy droga skręci na zachód.$b$bPamiętaj jednak, by nie zbaczać z drogi, $n. Ostatnio w lasach grasują niebezpieczne bestie.', 'Zanieś częściowo napełnione naczynie Corithrasowi Księżycowemu Gniewowi w Dolanaar.', '', '', '', '', '', '', 0),
(929, 'plPL', 'Korona ziemi', 'Najpierw opowiem ci więcej o zadaniu, które musisz wykonać. Druidzi w Darnassus korzystają z wody księżycowych studni Teldrassilu, a ich własną studnię trzeba co jakiś czas uzupełniać. W tych specjalnie wykonanych fiolkach możesz zbierać wodę z księżycowych studni.$b$bZanieś to naczynie do księżycowej studni pod Wioską Gwiezdnej Bryzy na wschodzie, napełnij je jej wodą i wróć do mnie. Gdy wykonasz zadanie, podejmę opowieść w miejscu, w którym przerwał ją Tenaron...', 'Napełnij nefrytową fiolkę i przynieś ją Corithrasowi Księżycowemu Gniewowi w Dolanaar.', '', 'Wróć do Corithrasa Księżycowego Gniewu w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(930, 'plPL', 'Świecący owoc', 'Spod liści tej świecącej rośliny zwisa duży, okrągły owoc.$B$BJesteś $gpewien:pewna;, że Denalan chciałby go zbadać.', 'Zanieś świecący owoc Denalanowi nad Jeziorem Al\'Ameth.', '', '', '', '', '', '', 0),
(931, 'plPL', 'Lśniący liść paproci', 'Liście tej rośliny lśnią w leśnym świetle, otaczając ją wijącą się, pulsującą aurą.$B$BSądzisz, że Denalan chciałby dostać taki okaz.', 'Przynieś lśniący liść paproci Denalanowi nad Jeziorem Al\'Ameth', '', '', '', '', '', '', 0),
(932, 'plPL', 'Wypaczona nienawiść', 'Muszę cię ostrzec, $n: ta sprawa musi zostać między nami. Satyrowie i tak przynoszą nam dość wstydu, a ten jest zdecydowanie zbyt blisko domu.$B$BNazywa się lord Melenas. Mieszka w pobliskiej jaskini zwanej Spaczoną Skałą, gdzie zgromadził sporą grupę grellich wojowników. Jego serce jest czarne jak noc, a on knuje coś wyjątkowo plugawego.$B$BOdnajdź go w tej jaskini, tuż na północ stąd, i przynieś mi jego głowę.', 'Zabij lorda Melenasa i przynieś jego głowę Tallonkaiowi Chyżemu Korzeniowi w Dolanaar.', '', 'Wróć do Tallonkaia Chyżego Korzenia w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(933, 'plPL', 'Korona ziemi', 'Kolejna księżycowa studnia znajduje się na południowy wschód od wejścia do Darnassus, na brzegu Sadzawek Arlithrien. Strażniczki mają kłopoty z patrolowaniem tej okolicy z powodu ataków i coraz większej wrogości furbolgów z plemienia Sękatej Sosny.$b$bZachowaj ostrożność, gdy będziesz szukać studni, i trzymaj broń pod ręką.', 'Napełnij turmalinową fiolkę i przynieś ją Corithrasowi Księżycowemu Gniewowi w Dolanaar.', '', 'Wróć do Corithrasa Księżycowego Gniewu w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(934, 'plPL', 'Korona ziemi', 'Na Teldrassilu nie wszystko jednak było dobrze. Starannie opracowane plany Jeleniorogiego dotyczące nowego Drzewa Świata spełniły się tak, jak tego oczekiwał, ale pojawił się jeden drobny problem – problem, któremu można przypisać wiele kłopotów na Teldrassilu.$b$bNie pora jednak jeszcze o tym mówić. Musisz odwiedzić ostatnią księżycową studnię, na północnym zachodzie, na Polanie Wyroczni. Pod konarami Drzewa Wyroczni leży pierwsza i najpotężniejsza z naszych studni. Nabierz fiolkę jej wody i wróć do mnie.', 'Napełnij ametystową fiolkę i przynieś ją Corithrasowi Księżycowemu Gniewowi w Dolanaar.', '', 'Wróć do Corithrasa Księżycowego Gniewu w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(935, 'plPL', 'Korona ziemi', 'Bez błogosławieństw Alexstrazy Życiodajnej i Nozdormu Wiekuistego wzrost Teldrassilu nie przebiega bez skazy. Donoszą o dziwnych bestiach, które wyłaniają się z samego gruntu drzewa, a oszalałe furbolgi napadają na podróżnych.$b$bMogę tylko mieć nadzieję, że arcydruid szybko znajdzie rozwiązanie, którego szuka. Przeleję wodę ze wszystkich fiolek, które $gprzyniosłeś:przyniosłaś;, do tego naczynia, a ty zaniesiesz je do Darnassus.$b$bOddaj je Fandralowi Jeleniorogiemu – znajdziesz go w gaju druidów.', 'Zanieś napełnione naczynie arcydruidowi Fandralowi Jeleniorogiemu w Darnassus.', '', '', '', '', '', '', 0),
(937, 'plPL', 'Zaczarowana polana', 'Wysłano mnie tu z niewielkim oddziałem Strażniczek, byśmy chroniły Drzewo Wyroczni przed harpiami, które uwiły gniazda wokół całej polany. Krok po kroku staramy się je odepchnąć.$b$bGdy Drzewo Wyroczni próbowało wysłać gońca z raportem do Darnassus, grupa harpii napadła na posłańca i go zabiła.$b$bJeśli czujesz się na siłach, udaj się do ich gniazd, zabij je i przynieś mi ich pasy jako dowód swoich czynów.', 'Zdobądź 6 pasów Krwawego Pióra i przynieś je strażniczce Aryni Rozdartej Chmurze na Polanie Wyroczni.', '', 'Wróć do strażniczki Aryni Rozdartej Chmury nad Jeziorem Źródlanym na Teldrassilu.', '', '', '', '', 0),
(938, 'plPL', 'Mgiełka', 'Futro tej szablobestii ma charakterystyczny szary kolor, który zlewa się z otaczającym lasem. Gdy tak leży, dostrzegasz, że jest ciężko ranna – na grzbiecie i brzuchu ma głębokie, poszarpane rany.$b$bUnosi łeb i spogląda na ciebie, a w jej niebieskich oczach lśni bystra inteligencja. Wygląda na to, że chce pójść za tobą.', 'Odprowadź Mgiełkę do strażniczki Aryni Rozdartej Chmury przy księżycowej studni w pobliżu Drzewa Wyroczni.', 'Bezpiecznie doprowadź Mgiełkę do strażniczki Aryni Rozdartej Chmury', 'Wróć do strażniczki Aryni Rozdartej Chmury na Polanie Wyroczni na Teldrassilu.', '', '', '', '', 0),
(940, 'plPL', 'Teldrassil', 'Las szepcze o twoich mężnych czynach, $n. Gdy poczułam, że harpie zostały przepędzone z gniazd, las ogarnął głębszy spokój, a jego stworzenia znów poczuły się bezpiecznie. Bałam się wysłać do arcydruida kolejnego posłańca, ale wiem, że ty bezpiecznie dostarczysz mu moją wiadomość.$b$bZanieś mu to i wiedz, że las bezpiecznie poprowadzi cię swoimi ścieżkami aż do kamiennego lasu.', 'Dostarcz raport Drzewa Wyroczni arcydruidowi Fandralowi Jeleniorogiemu w Darnassus.', '', '', '', '', '', '', 0),
(941, 'plPL', 'Zasadzenie serca', 'Usunąłem z serca ten plugawy mech, ale ono wciąż jest skażone...$B$BSpróbuj umieścić serce w mojej donicy. Jest pełna odżywczej gleby, która może je oczyścić i uleczyć.', 'Zasadź skażone serce w donicy Denalana.', '', '', '', '', '', '', 0),
(978, 'plPL', 'Dziczołaki dotknięte przez księżyc', 'Pióra dziczołaków z Zaziemia zdają się nosić ślady magicznych właściwości. Te moce... stworzenia chyba nimi nie władają; to raczej coś wrodzonego dla tego gatunku – część samej jego istoty.$B$BPodczas badań usłyszałem, że liczne dziczołaki zamieszkują śnieżne krainy Zimozdroju. Czy tamte stworzenia mogą mieć takie same moce? Proszę, pomóż mi znaleźć odpowiedź, $N. Udaj się do Zimozdroju, zbierz pióra, które spadły na ziemię, i wróć do mnie.', 'Zbierz 10 piór dotkniętych przez księżyc w Zimozdroju, a następnie wróć do Erelasa Bursztynowego Nieba w Wiosce Rut\'theran.', '', 'Wróć do Erelasa Bursztynowego Nieba w Wiosce Rut\'theran na Teldrassilu.', '', '', '', '', 0),
(979, 'plPL', 'Odnajdź Ranshallę', 'Tak, tak, te pióra zdają się nosić ten sam magiczny urok, który zauważyłem wcześniej... Choć nie wiem, co możemy odkryć, gorąco zachęcam cię, byś dalej $gszukał:szukała; odpowiedzi, $N.$B$BMoja koleżanka niedawno wyruszyła do Zimozdroju, by obserwować tamtejsze dziczołaki w ich naturalnym środowisku. Może ją dogonisz i sprawdzisz, czego się dowiedziała?', 'Odnajdź Ranshallę we wschodniej części Zimozdroju.', '', '', '', '', '', '', 0),
(997, 'plPL', 'Ziemia dla Denalana', 'Zmierzasz na południe? Nad Jezioro Al\'Ameth? Jeśli tak, mam do ciebie prośbę...$B$BMój kolega Denalan ma obóz na wschodnim krańcu jeziora, gdzie bada roślinność Teldrassilu i prowadzi na niej doświadczenia. Zamówił z Darnassus paczkę rzadkiej ziemi, ale przesyłka się spóźniła i dopiero niedawno dotarła tu, do Dolanaar.$B$BCzy możesz mu ją zanieść?', 'Zanieś paczkę rzadkiej ziemi Denalanowi nad Jeziorem Al\'Ameth.', '', '', '', '', '', '', 0),
(1581, 'plPL', 'Eliksiry dla Ostrolistów', 'Nasz sklep z ziołami i alchemią świetnie prosperuje, ale mój mąż spędza tyle czasu na mieszaniu mikstur, że nigdy nie mamy czasu dla siebie.$B$BMożesz nam pomóc?$B$BJeśli przyniesiesz mi zapas gotowych eliksirów, chętnie się z tobą wymienię. Mam kilka rzadkich ziół, które mogą ci się przydać.', 'Przynieś 6 eliksirów lwiej siły i 2 eliksiry pomniejszej obrony Syral Ostrolist w Dolanaar.', '', 'Wróć do Syral Ostrolist na Teldrassilu.', '', '', '', '', 0),
(1684, 'plPL', 'Elanaria', 'Witaj, $gwojowniku:wojowniczko;. Twoje umiejętności rosną, ale twoja profesja kryje w sobie więcej, niż sądzisz. Aby robić dalsze postępy, musisz wkrótce znaleźć nauczyciela.$B$BWojowniczka Elanaria mieszka w Darnassus, na Tarasie Wojowników. Ona może cię szkolić.', 'Porozmawiaj z Elanarią.', '', '', '', '', '', '', 0),
(2159, 'plPL', 'Przesyłka do Dolanaar', 'Witaj, $N. Czy możesz mi pomóc? Mam paczkę ziół, którą muszę dostarczyć do Dolanaar. Wciąż jednak mam sprawy do załatwienia z druidami z Cienistego Jaru i nie mogę jeszcze odejść.$B$BCzy możesz dostarczyć tę paczkę za mnie? Trzeba ją przekazać karczmarzowi Keldamyrowi w gospodzie w Dolanaar. Miasteczko leży przy drodze, na południu.', 'Zanieś przesyłkę do Dolanaar karczmarzowi Keldamyrowi.', '', '', '', '', '', '', 0),
(2241, 'plPL', 'Zakochany po uszy', 'Mówią, że jestem „zadurzony”, cokolwiek to znaczy.$B$BNo dobrze, każdą chwilę na jawie spędzam na myśleniu o Syurnie. No dobrze, mój dom jest pełen obrazów i rysunków Syurny. No dobrze, często całymi dniami nie jem, nie śpię i nie piję, opłakując miłość, która mogła nas połączyć. Czy to takie złe?$B$BA teraz ona nie chce mnie widzieć! MNIE! Próbowałem wysyłać jej wiadomości, ale ona nie rozmawia z nikim, kto nie jest łotrzykiem.$B$BMożesz zanieść jej ten kwiat? Nie zapomnij powiedzieć, że jest od Jannoka.', 'Zanieś różę Jannoka Syurnie w Darnassus.', '', '', '', '', '', '', 0),
(2259, 'plPL', 'Erion Szept Cienia', 'Nie martw się, $N, nie wysyłam cię do Syurny. Erion wzywa cię do Enklawy Cenariona. Pospiesz się!', 'Skontaktuj się z Erionem Szeptem Cienia w Darnassus.$B', '', '', '', '', '', '', 0),
(2399, 'plPL', 'Wykiełkowane liście paproci', '', '', '', '', '', '', '', '', 0),
(2438, 'plPL', 'Szmaragdowy łapacz snów', 'Kiedyś dostałem szmaragdowy łapacz snów od Gaerolasa Talvethrena, opiekuna druidów w Kurhanie Ban\'ethil. Ten potężny amulet potrafi czerpać energię ze Szmaragdowego Snu i przynosi szczęście temu, kto go nosi.$B$BNiestety, nie zdołałem go zabrać z mojej komody w Wiosce Gwiezdnej Bryzy... Gwiezdna Bryza była niegdyś spokojnym miejscem, ale teraz padła ofiarą skażonych furbolgów, które się tam zadomowiły.$B$BCzy $gzechciałbyś:zechciałabyś; odzyskać mój łapacz snów, $N?', 'Przynieś szmaragdowy łapacz snów Tallonkaiowi Chyżemu Korzeniowi w Dolanaar.', '', 'Wróć do Tallonkaia Chyżego Korzenia nad Jeziorem Al\'Ameth na Teldrassilu.', '', '', '', '', 0),
(2459, 'plPL', 'Ferocitas Pożeracz Snów', 'Szmaragd... Zniknął! Mój łapacz snów został uszkodzony!$B$BNa północ od Gwiezdnej Bryzy przebywa banda mistyków Sękatej Sosny. Słyszałem, że ich przywódca, Ferocitas Pożeracz Snów, nosi naszyjnik, który nocą świeci na zielono. Teraz, gdy widzę mój łapacz snów, jestem pewien, że to on ukradł mój szmaragd... Nigdy nie pojmie, że jego moc jest dla niego bezużyteczna.$B$BOdnajdź zaginiony klejnot, $N. A skoro już tam będziesz, przetrzeb też skażonych mistyków.', 'Tallonkai Chyży Korzeń z Dolanaar chce, żebyś $gzabił:zabiła; 7 mistyków Sękatej Sosny i $godnalazł:odnalazła; zaginiony klejnot.', '', 'Wróć do Tallonkaia Chyżego Korzenia w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(2498, 'plPL', 'Powrót do Denalana', 'Właśnie dostałem wieść, że Denalan znad Jeziora Al\'Ameth odkrył, co może być przyczyną guzów nękających drzewczyki. Porozmawiaj z nim i powiedz, że to ja cię przysłałem.$B$BPospiesz się, $N – on potrzebuje naszej pomocy.', 'Rellian Zielona Iglica chce, żebyś $gporozmawiał:porozmawiała; z Denalanem nad Jeziorem Al\'Ameth.', '', '', '', '', '', '', 0),
(2499, 'plPL', 'Dębochmur', 'W jaskini na południowym brzegu jeziora drzewczyk zwany Dębochmurem szerzy skażenie wśród wszystkich stworzeń, które zamieszkują okolice Jeziora Al\'Ameth.$B$BNie odważyłem się podejść zbyt blisko, ale nawet z oddali widać to wyraźnie: Dębochmura zatruwa największy guz, jaki kiedykolwiek widziałem... Nazwałbym go wręcz gigantycznym.$B$B$N, już bardzo mi $gpomogłeś:pomogłaś;, ale proszę cię o jeszcze jedno. Wytrop Dębochmura i zdobądź ten guz – usuń to źródło skażenia z mojego domu.', 'Denalan znad Jeziora Al\'Ameth prosi cię o zdobycie gigantycznego guza Dębochmura.', '', 'Wróć do Denalana na Teldrassilu.', '', '', '', '', 0),
(2541, 'plPL', 'Śpiący druid', 'Szamani Sękatej Sosny, którzy zamieszkują to miejsce, odkryli sposób, by oddzielić ducha śpiącego druida od jego ciała. Furbolgi ożywiły moje ciało i wykorzystują je do atakowania każdego, kto próbuje zbadać Kurhan Ban\'ethil. Utknąłem w Szmaragdowym Śnie i nie mam jak temu zapobiec.$B$BMusisz mi pomóc. Szamani Sękatej Sosny noszą dziwny amulet, za pomocą którego odprawiają ten rytuał. Chciałbym mu się przyjrzeć. Proszę, $N, przynieś mi jeden.', 'Przynieś szamański amulet wudu Obenowi Wściekłemu Pazurowi w Kurhanie Ban\'ethil.', '', 'Wróć do Obena Wściekłego Pazura na Teldrassilu.', '', '', '', '', 0),
(2561, 'plPL', 'Druid Szponów', 'Zbadałem ten amulet, $N, i już wiem, co trzeba zrobić. Proszę, weź go i zrób, o co cię poproszę.$B$BUdaj się w najgłębsze zakamarki Kurhanu Ban\'ethil. Znajdziesz tam moje pozbawione duszy ciało... Choć żałuję tego, co zaraz powiem, nie widzę innego sposobu, by uwolnić się spod władzy plemienia Sękatej Sosny.$B$BAbym mógł im się wyrwać, musisz zabić moje ciało. Gdy to zrobisz, użyj amuletu wudu na moich zwłokach. A kiedy wykonasz to zadanie, wróć do mnie, proszę.', 'Zabij pozbawione duszy ciało Obena Wściekłego Pazura, a następnie użyj amuletu wudu.', 'Uwolnij ducha Obena Wściekłego Pazura', 'Wróć do Obena Wściekłego Pazura w Kurhanie Ban\'ethil.', '', '', '', '', 0),
(2939, 'plPL', 'W poszukiwaniu wiedzy', 'Choć ruiny Feralas bywają bardzo niebezpieczne, wiele mogą powiedzieć o tym, co się tu wydarzyło.$B$BKilka dni temu, przeszukując gruzy na południu, znalazłem coś, co wygląda na zwykły kostur. Nie mogę jednak pozbyć się wrażenia, że kryje się w nim coś więcej. Razem z Angelas ślęczymy nad naszymi księgami, ale nie możemy nic o nim znaleźć.$B$BMam w Darnassus znajomą uczoną, która być może powie nam, co to jest, $N. Może pójdziesz z nią porozmawiać i sprawdzisz, czy zdoła nam pomóc?', 'Porozmawiaj z Daryn Jasny Wiatr w Wiosce Rut\'theran.', '', '', '', '', '', '', 0),
(2940, 'plPL', 'Feralas: historia', 'Wygląda na to, że nikt nie otwierał tej księgi od bardzo dawna. Okładki ma mocno zniszczone, a strony pożółkłe, ale gdy się jej przyglądasz, dochodzisz do wniosku, że to może być właśnie to, czego szuka Troyas.$B$BBierzesz ją do ręki, ale uświadamiasz sobie, że przed pożyczeniem wypadałoby zapytać o zgodę.', 'Zapytaj Daryn Jasny Wiatr, czy możesz pożyczyć jej księgę.', '', '', '', '', '', '', 0),
(2941, 'plPL', 'Pożyczka', 'W swoim życiu zgłębiałam wiele dziedzin, a ostatnio fascynują mnie szczękogryzy zamieszkujące plażę w Zaziemiu. Szczególnie chciałabym zobaczyć jednego z nich, olbrzymiego szczękogryza o imieniu Gammerita. Chętnie wybrałabym się tam sama, ale badania trzymają mnie tutaj. Myślę, że jej zdjęcie byłoby najlepszym zastępstwem.$B$BZanieś ten list do Curgle Cranklehop w Tanaris. Zbudowała dla mnie wynalazek, który potrafi uchwycić obraz. Nazwała to chyba „fotką”...', 'Zanieś list do Curgle Cranklehop w Tanaris.', '', '', '', '', '', '', 0),
(2943, 'plPL', 'Powrót do Troyasa', 'Oto ona, $N. Proszę, uważaj na moją księgę.$B$BA teraz się pospiesz. Troyas na pewno nie może się doczekać twojego powrotu.', 'Dostarcz księgę Troyasowi Księżycowej Bryzie w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(2944, 'plPL', 'Superpstrykacz FX', 'Możesz jako $gpierwszy:pierwsza; obejrzeć mój nowy wynalazek, $N. Wystarczy wycelować w to, co chcesz sfotografować, i nacisnąć przycisk.$B$BJak się nazywało to stworzenie z Zaziemia, o którym $gwspominałeś:wspominałaś;? Gammerita? Cóż, powodzenia w szukaniu. Jestem pewna, że Daryn bardzo się ucieszy ze zdjęcia, które jej przyniesiesz.$B$BTak czy inaczej, oto Superpstrykacz. Baw się dobrze!', 'Użyj Superpstrykacza FX, aby zrobić zdjęcie Gammericie, a następnie wróć do Daryn Jasny Wiatr w Wiosce Rut\'theran.', '', 'Wróć do Daryn Jasny Wiatr w Wiosce Rut\'theran na Teldrassilu.', '', '', '', '', 0),
(3022, 'plPL', 'Ostrożnie, kruche!', '$N, widzę, że pragniesz poświęcić się mojej szczytnej sprawie. Tak, oczywiście, możesz coś dla mnie zrobić!$B$BZanieś tę skrzynkę jaj Erelasowi Bursztynowemu Niebu. To druid, który opiekuje się tymi jajami, pomaga pisklętom się wykluć, a potem szkoli młode hipogryfy. Znajdziesz go na Teldrassilu, w małej wiosce na południu, zwanej Rut\'theran.', 'Dostarcz starannie zapakowaną skrzynkę Erelasowi Bursztynowemu Niebu w Wiosce Rut\'theran.', '', '', '', '', '', '', 0),
(3116, 'plPL', 'Prosty symbol', 'Ten symbol przekazał mi posłaniec od naszej nauczycielki wojowników, Alyissii. Wygląda na to, że Alyissia chce z tobą pomówić, gdy znajdziesz chwilę. Przeczytaj go, a następnie zanieś jej.', 'Przeczytaj prosty symbol i porozmawiaj z Alyissią w Cienistym Jarze.', '', '', '', '', '', '', 0),
(3117, 'plPL', 'Wyryty symbol', 'Ten symbol przekazał mi posłaniec od naszej nauczycielki łowców, Ayanny. Wygląda na to, że Ayanna chce z tobą pomówić, gdy znajdziesz chwilę. Przeczytaj go, a następnie zanieś jej.', 'Przeczytaj wyryty symbol i porozmawiaj z Ayanną Wiecznokroką na szczycie Aldrassilu w Cienistym Jarze.', '', '', '', '', '', '', 0),
(3118, 'plPL', 'Zaszyfrowany symbol', 'Ten symbol przekazał mi posłaniec od naszego nauczyciela łotrzyków, Frahuna. Wygląda na to, że Frahun chce z tobą pomówić, gdy znajdziesz chwilę. Przeczytaj go, a następnie zanieś jemu.', 'Przeczytaj zaszyfrowany symbol i porozmawiaj z Frahunem Szeptem Cienia w Cienistym Jarze.', '', '', '', '', '', '', 0),
(3119, 'plPL', 'Uświęcony symbol', 'Ten symbol przekazał mi posłaniec od naszej nauczycielki kapłanów, Shandy. Wygląda na to, że Shanda chce z tobą pomówić, gdy znajdziesz chwilę. Przeczytaj go, a następnie zanieś jej.', 'Przeczytaj uświęcony symbol i porozmawiaj z Shandą w Aldrassilu.', '', '', '', '', '', '', 0),
(3120, 'plPL', 'Zielony symbol', 'Ten symbol przekazał mi posłaniec od naszego nauczyciela druidów, Mardanta. Wygląda na to, że Mardant chce z tobą pomówić, gdy znajdziesz chwilę. Przeczytaj go, a następnie zanieś jemu.', 'Przeczytaj zielony symbol i porozmawiaj z Mardantem Mocnym Dębem w drzewie Aldrassil w Cienistym Jarze.', '', '', '', '', '', '', 0),
(3519, 'plPL', 'Przyjaciel w potrzebie', 'Uuuch... Pająk zwany Githyiss Plugawy dotkliwie mnie ukąsił, kiedy badałem pajęczą jaskinię niedaleko stąd. Jestem pewien, że zostałem ciężko otruty – musisz mi pomóc.$B$BProszę, powiedz o tym Diranii Srebrny Blask. Ona zdoła mi pomóc.$B$BPospiesz się... Tak mi się kręci w głowie...', 'Porozmawiaj z Diranią Srebrny Blask w Cienistym Jarze.', '', '', '', '', '', '', 0),
(3521, 'plPL', 'Odtrutka Iverrona', 'Chyba zdołamy pomóc Iverronowi – znam odtrutkę, która powinna zadziałać na tę truciznę. Zanim jednak ją przygotuję, potrzebuję kilku składników.$B$BBędą mi potrzebne hiacyntowe grzyby. Rosną pod drzewami, ale możesz je też zebrać od grelli na południe stąd – chyba bardzo je sobie upodobały. Potrzebuję też lilii księżycowego płatka, które rosną tylko wokół oczek wodnych.$B$BOstatni składnik może okazać się najtrudniejszy do zdobycia. Od tych samych pająków, które otruły Iverrona, zdobądź posokę z Pajęczego Lasu.', 'Zbierz 7 hiacyntowych grzybów, 4 lilie księżycowego płatka i 1 posokę z Pajęczego Lasu dla Diranii Srebrny Blask w Cienistym Jarze.', '', 'Wróć do Diranii Srebrny Blask w Aldrassilu na Teldrassilu.', '', '', '', '', 0),
(3522, 'plPL', 'Odtrutka Iverrona', 'Odtrutka jest gotowa, $N. Dopilnuj, proszę, żeby Iverron ją wypił.$B$BMusisz jednak coś wiedzieć – ta odtrutka... zachowa skuteczność tylko przez 5 minut. Musisz dostarczyć mu ją na czas.$B$BBiegnij jak wiatr, $N.', 'Dostarcz odtrutkę Iverronowi, zanim upłynie czas. Iverrona znajdziesz przy jaskini na północy.', '', '', '', '', '', '', 0),
(3661, 'plPL', 'Ulubieńcy Eluny?', 'Dziczołaki to bardzo nieprzewidywalne stworzenia, $N. Choć potrafią być niezwykle łagodne, wpadają w straszliwą furię, gdy zagrożone jest coś, co uważają za ważne.$B$BPodobno te istoty stworzyła Elune, a ja chciałbym się przekonać, czy to prawda.$B$BNiedawno słyszałem o dziczołakach żyjących w Zaziemiu – okrutnych, prymitywnych i dzikich sowostworach. Można je spotkać wśród tamtejszej dzikiej zwierzyny. Zbierzesz dla mnie trochę piór dziczołaków?', 'Zbierz 15 piór dziczołaków z Zaziemia dla Erelasa Bursztynowego Nieba w Wiosce Rut\'theran.', '', 'Wróć do Erelasa Bursztynowego Nieba w Wiosce Rut\'theran na Teldrassilu.', '', '', '', '', 0),
(4161, 'plPL', 'Przepis kaldorei', 'Dawno temu nocne elfy nazywano kaldorei – to imię znaczy „dzieci gwiazd”. Poznawanie przeszłości to ważny krok na twojej ścieżce jako $c, $N, więc słuchaj uważnie tego, co mam ci do powiedzenia.$B$BKaldorei zawsze byli bardzo dumni ze swojej harmonijnej więzi z naturą. Oznacza to, że bierzemy od natury tylko to, co niezbędne, i oddajemy jej w zamian. Ta równowaga wiele nam dała, $N.$B$BIdź i zbierz siedem małych pajęczych odnóży – nie więcej – i wróć do mnie.', 'Zbierz 7 małych pajęczych odnóży dla Zarrina w Dolanaar.', '', 'Wróć do Zarrina w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(4495, 'plPL', 'Dobry przyjaciel', 'Mój przyjaciel Iverron zwykle odwiedza mnie codziennie o tej samej porze. Dziwne jest to, że dziś w ogóle się nie pojawił – spóźnia się już kilka godzin.$B$BPrzyznaję, trochę się martwię, $N. Iverron spędza dużo czasu przy jaskini na północy, a na pewno wiesz, jak tam niebezpiecznie – wszędzie pająki!$B$BJeśli jednak będziesz tamtędy przechodzić, rozejrzyj się za nim, dobrze?', 'Odszukaj Iverrona przy jaskini na północy.', '', '', '', '', '', '', 0),
(4901, 'plPL', 'Strażnicy ołtarza', 'Na samym szczycie grani znajduje się, jak sądzę, ołtarz bogini Eluny. Z tego, co udało mi się ustalić, musimy zapalić pięć pochodni, po jednej w każdej jaskini, a wtedy uzyskamy dostęp do samego ołtarza.$B$BPrzepisałam zaklęcia wyryte w kamieniu w starożytnych ruinach Kel\'Theril, które – jak sądzę – są kluczem do otwarcia ołtarza. Będę potrzebować twojej pomocy przy zapalaniu pochodni, podczas gdy ja będę recytować zaklęcie.$B$BJeśli nam się uda, zdasz Erelasowi relację z naszych odkryć!', 'Chroń Ranshallę, gdy będzie próbowała przywrócić do działania Ołtarz Eluny. Zdaj relację z odkryć Erelasowi Bursztynowemu Niebu w Wiosce Rut\'theran.', 'Odkryj tajemnicę Ołtarza Eluny', 'Wróć do Erelasa Bursztynowego Nieba w Wiosce Rut\'theran na Teldrassilu.', '', '', '', '', 0),
(5250, 'plPL', 'Spadająca Gwiazda', 'W Zimozdroju, na północ od Spaczonej Kniei, jest wiele starożytnych elfich ruin. To surowa kraina, ale kryje wiele tajemnic i miejsc do zbadania.$B$BBadania tak mnie tu pochłaniają, że od dawna nie miałam okazji wybrać się do Zimozdroju. Ale ty możesz się tam udać i zbadać ruiny – nic nie stoi na przeszkodzie.$B$BGdy już tam będziesz, poszukaj Wynda Nocnego Pościgu. Spędza większość czasu w Wiosce Spadającej Gwiazdy i wie wiele o tej okolicy.$B$BPowiedz mu, że się u mnie uczysz...', 'Odnajdź Wioskę Spadającej Gwiazdy w Zimozdroju i porozmawiaj z Wyndem Nocnym Pościgiem.', '', '', '', '', '', '', 0),
(5621, 'plPL', 'Szaty księżyca', 'Potrzebuję twojej pomocy, $N. Muszę zostać tutaj i szkolić innych uczniów, ale ty możesz pomóc jednej z naszych Strażniczek, która leży ranna tuż na południe od Dolanaar. Odniosła rany podczas patrolowania miasteczka i przyda jej się nasza pomoc. Ma na imię Shaya.$B$BGdy ją znajdziesz, ulecz jej rany, a potem wzmocnij jej ciało swoimi zaklęciami. Dzięki temu dłużej będzie bezpieczna, jeśli natknie się na kłopoty. Gdy wypełnisz swój obowiązek wobec Eluny, wróć tu do mnie.', 'Odnajdź Strażniczkę Shayę i ulecz jej rany czarem Pomniejsze leczenie (ranga 2). Następnie rzuć na nią Słowo mocy: Wytrwałość i wróć do Laurny Poranne Światło w Dolanaar.', '', 'Wróć do Laurny Poranne Światło nad Jeziorem Al\'Ameth na Teldrassilu.', 'Ulecz i wzmocnij Strażniczkę Shayę', '', '', '', 0),
(5622, 'plPL', 'W łasce Eluny', '$N, gdy skończysz swoje sprawy tutaj, w Cienistym Jarze, musisz udać się do Dolanaar. Znajdziesz tam Laurnę Poranne Światło. Dalej wprowadzi cię w drogi Eluny i to u niej zdobędziesz swoje pierwsze szaty, oznaczające twoją pozycję $gkapłana:kapłanki; Eluny.$B$BUważaj na siebie i niech nic złego nie spotka cię w podróży.', 'Porozmawiaj z Laurną Poranne Światło na Teldrassilu.', '', '', '', '', '', '', 0),
(6341, 'plPL', 'Dary Teldrassilu', 'Rybakom z Wioski Rut\'theran wiedzie się bardzo dobrze, bo ryby są tu wyjątkowo duże i jest ich pod dostatkiem. Chciałabym porównać tutejsze dary natury z tymi z lądu stałego.$B$BMam kolekcję rybich ości i łusek, którą chciałabym przekazać mojemu znajomemu z Mrocznego Wybrzeża. Nazywa się Laird i sprzedaje ryby w Auberdine.$B$BZanieś moją kolekcję naszemu mistrzowi hipogryfów, Vesprystusowi, i porozmawiaj z nim o podróży do Auberdine.', 'Zanieś kolekcję Nessy Vesprystusowi.', '', '', '', '', '', '', 0),
(6342, 'plPL', 'Lot do Auberdine', 'Z Rut\'theran do Auberdine można się dostać na dwa sposoby: promem albo na hipogryfie. Oba są szybkie i niezawodne, ale jeśli jeszcze nie $glatałeś:latałaś; do Auberdine na hipogryfie, radzę to zrobić.$B$BWarto porozmawiać z mistrzem hipogryfów w każdym mieście, w którym jest. Gdy już z nim porozmawiasz, zdołasz tam polecieć z innych miast.$B$BOto kolekcja Nessy. Porozmawiaj ze mną ponownie, gdy będziesz $ggotowy:gotowa; do lotu do Auberdine, i dostarcz kolekcję Nessy Lairdowi.', 'Poleć do Auberdine na hipogryfie od mistrza hipogryfów Vesprystusa, a następnie zanieś kolekcję Nessy Lairdowi.', '', '', '', '', '', '', 0),
(6343, 'plPL', 'Powrót do Nessy', 'Muszę wysłać Nessie odpowiedź. Bardzo ją zainteresuje, jak bardzo tutejsze ryby różnią się od tych przy wybrzeżach Teldrassilu. Możemy jedynie zgadywać, co jest przyczyną, ale podejrzewam, że to samo drzewo świata wpływa na okoliczną przyrodę!$B$BProszę, zanieś tę odpowiedź Nessie. Jeśli chcesz wrócić do Rut\'theran na hipogryfie, porozmawiaj z mistrzynią hipogryfów Caylais Księżycowe Pióro. Jeśli wolisz prom, regularnie odpływa z przystani na północnym zachodzie.', 'Zanieś odpowiedź Lairda Nessie Cienistej Pieśni.', '', '', '', '', '', '', 0),
(6344, 'plPL', 'Nessa Cienista Pieśń', 'Moja przyjaciółka, Nessa Cienista Pieśń, handluje rybami w Wiosce Rut\'theran. Musi przekazać paczkę na Mroczne Wybrzeże i szuka kogoś, kto jej pomoże.$B$BJeśli cię to interesuje, to aby dotrzeć do Nessy, musisz skorzystać z portalu w Darnassus prowadzącego do Wioski Rut\'theran. Znajdziesz go na zachód od Ogrodów Świątynnych.', 'Porozmawiaj z Nessą Cienistą Pieśnią.', '', '', '', '', '', '', 0),
(7383, 'plPL', 'Korona ziemi', 'Na Teldrassilu nie wszystko jednak było dobrze. Starannie opracowane plany Jeleniorogiego dotyczące nowego Drzewa Świata spełniły się tak, jak tego oczekiwał, ale pojawił się jeden drobny problem – problem, któremu można przypisać wiele kłopotów na Teldrassilu.$b$bNie pora jednak jeszcze o tym mówić. Musisz odwiedzić ostatnią księżycową studnię, na północnym zachodzie, na Polanie Wyroczni. Pod konarami Drzewa Wyroczni leży pierwsza i najpotężniejsza z naszych studni. Nabierz fiolkę jej wody i wróć do mnie.', 'Napełnij ametystową fiolkę i przynieś ją Corithrasowi Księżycowemu Gniewowi w Dolanaar.', '', 'Wróć do Corithrasa Księżycowego Gniewu w Dolanaar na Teldrassilu.', '', '', '', '', 0),
(8715, 'plPL', 'Nestor Ostrolist', '', '', '', '', '', '', '', '', 0),
(8734, 'plPL', 'Tyrande i Remulos', 'Tyrande zostanie powiadomiona, $gśmiertelniku:śmiertelniczko;. Shan\'do Burzogniewny przygotował mnie na taką ewentualność.$B$BTeraz musisz udać się do Gaju Luny i porozmawiać z Remulosem. Przekaże ci dalsze wskazówki dotyczące przywołania Eranikusa.$B$BWszyscy życzymy ci wiele szczęścia.', 'Udaj się do Gaju Luny i porozmawiaj z opiekunem Remulosem.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(456, 'plPL', 'Dobrze $gwypełniłeś:wypełniłaś; swoje obowiązki, $N.', 0),
(457, 'plPL', 'Dobrze $gdowiodłeś:dowiodłaś; swojego oddania naturze, $N. Taki $gmłody:młoda; $c jak ty ma przed sobą obiecującą przyszłość.', 0),
(458, 'plPL', 'Widzę, że mnie $godnalazłeś:odnalazłaś;, $N. Melithar to mądry druid, skoro cię przysłał.', 0),
(459, 'plPL', 'Twoja służba dla stworzeń Cienistego Jaru zasługuje na nagrodę, $N.$b$b$GPotwierdziłeś:Potwierdziłaś; jednak moje obawy. Skoro nawet grelle zostały skażone przez spaczony mech, strach pomyśleć, co stało się z furbolgami z plemienia Sękatej Sosny, które niegdyś tu żyły.$b$bJeśli trafisz do Dolanaar, odszukaj uczonego druida Athridasa Niedźwiedziego Płaszcza. On również troszczy się o dobro lasu.', 0),
(475, 'plPL', 'Chwała duchom lasu, że jesteś! Wiedziałem, że Athridas wyczuje kłopoty i przyśle pomoc.', 0),
(476, 'plPL', 'Na gwiazdy! To doprawdy niepokojące!', 0),
(483, 'plPL', 'Udało ci się, $N! Dobra robota. I to, dodam, w samą porę.', 0),
(486, 'plPL', '$N, $gdowiodłeś:dowiodłaś;, że z ciebie $gnader godny i zdolny:nader godna i zdolna; $c. Ktoś z nocnych elfów, kto tak pewnie kroczy ścieżką honoru jak ty, z pewnością zdobędzie na tym świecie wielką chwałę.$b$bNiech duchy lasu chronią cię, dokądkolwiek zawiodą cię twoje wędrówki.', 0),
(487, 'plPL', 'Dobrze $gprzysłużyłeś:przysłużyłaś; się mieszkańcom Dolanaar i Darnassus, $N. Jako jedna ze Strażniczek Teldrassilu składam ci wyrazy uznania.', 0),
(488, 'plPL', 'Cha, cha! Doskonale, doprawdy.$b$bKto by pomyślał, że na posyłki u mnie, Zenna Plugawego Kopyta, będzie biegać $R? Na pewno nie ja! Ale tak to już bywa... ten nasz ukochany świat pełen jest niespodzianek.$b$bHip, hip, hurra na cześć naiwnych i łatwowiernych!', 0),
(489, 'plPL', 'Ach, co za $gsłodki:słodka; $R! Wiedziałem, że się przydasz!', 0),
(916, 'plPL', 'Dziękuję, $N. Gdy wrócę do Darnassus, porównam jad z tych gruczołów z jadem innych pająków. Wierzę, że będzie miał właściwości związane z niedawnym wzrostem naszego nowego drzewa świata.', 0),
(917, 'plPL', 'Ach, bardzo dobrze. Każę przewieźć to jajo i jad do Darnassus, a sam wrócę tam, gdy skończę tu badania. Spodziewam się, że te okazy wiele mi powiedzą, $N. Bardzo mi $gpomogłeś:pomogłaś;.', 0),
(918, 'plPL', 'Masz je. To dobrze!$b$bZasadzę te nasiona w specjalnej glebie, którą przygotowałem. Wierzę, że wyrosną z nich znacznie łagodniejsze drzewczyki. Może później zobaczysz efekty!', 0),
(919, 'plPL', 'To sporo! Obawiam się, że rozprzestrzeniają się w niebezpiecznym tempie. Mam nadzieję, że rozwiążę zagadkę tego, co je skaża.$b$bDziękuję za pomoc, $N. Dzięki twoim staraniom ta ziemia jest czystsza.', 0),
(920, 'plPL', 'Ach, $N. Liczyłem, że szybko odpowiesz na moje wezwanie. Mam ważne zadanie, które chciałbym ci powierzyć.', 0),
(921, 'plPL', '$GPoznałeś:Poznałaś; więc pierwszą część opowieści o tym, co nastąpiło po bitwie o Górę Hyjal. Wiele jeszcze zostało do opowiedzenia, a zadanie, które tu $grozpocząłeś:rozpoczęłaś;, będzie ci towarzyszyć przez całą wędrówkę po Teldrassilu, aż do Darnassus.', 0),
(922, 'plPL', 'Ach, nasiono drzewczyka? Chciałem spróbować wyhodować jedno z nich, by pomóc Denalanowi w badaniach.$b$bObawiam się jednak, że wiele drzewczyków toczy skażenie, a nasiona takich stworzeń dziedziczą skazę rodzica. Ich uzdrowienie przekracza moje umiejętności.$b$bDenalan ma wielki talent do wszystkiego, co rośnie. Może znajdzie lekarstwo dla przyszłych drzewczyków. Może jest ich jedyną nadzieją.', 0),
(923, 'plPL', 'Dobra robota! Te guzy to objaw choroby drzewczyków. Są pełne trucizny, którą musimy usunąć z naszej nowej ziemi.$b$bZajmę się nimi. Dziękuję, $N.', 0),
(927, 'plPL', '...Co to jest? Serce drzewczyka?? Pokrywa je plugawy mech!$b$bDziękuję, że mi je $gprzyniosłeś:przyniosłaś;, $N. Zbadam to serce i, jeśli szczęście dopisze, ustalę, czym jest ten mech.', 0),
(928, 'plPL', 'Ach, rozumiem. Przysłał cię Tenaron. Cóż, wygląda na to, że mamy wiele do omówienia, wiele do zrobienia i mało czasu.$B$BChyba najlepiej od razu zacznijmy.', 0),
(929, 'plPL', 'Po bitwie o Górę Hyjal zostaliśmy bez przewodnictwa. Nordrassil dymił od ognia, który rozpętał, a nasza nieśmiertelność – sama istota naszego bytu! – została utracona.$B$BTo właśnie w tym trudnym czasie Zdrajca wydostał się z więzienia, a shan\'do Burzogniewny zniknął. Był to mroczny czas dla wszystkich.', 0),
(930, 'plPL', '$GZnalazłeś:Znalazłaś; to na Teldrassilu? Intrygujące... to egzotyczny owoc. Być może jego nasiona przywędrowały tu z daleka. Może nawet aż z Azeroth! I jest w tym owocu coś... wygląda na to, że bardzo dziwnie zareagował z glebą Teldrassilu.$b$bDziękuję, $N. A teraz wybacz, muszę go dokładniej zbadać...', 0),
(931, 'plPL', 'Skąd to masz? Nie widziałem takiej rośliny od czasu mojej wyprawy na Moczary Smutków... dziesiątki lat temu! Zdumiewające, że okaz dotarł aż na Teldrassil. I że urósł do takich rozmiarów!$b$bDziękuję, $N. Wybacz mi zwięzłość, ale chciałbym przeprowadzić na tym liściu pewien test...', 0),
(932, 'plPL', 'Skoro lord Melenas spoczął na wieki, mogę wreszcie zająć się innymi sprawami. Dziękuję ci, $N.', 0),
(933, 'plPL', 'Shan\'do Burzogniewny nigdy nie powrócił, a wśród druidów zapanował zamęt – do dziś nie wiemy, co się z nim stało. Pod nieobecność Malfuriona przywództwo nad druidami przejął arcydruid Fandral Jeleniorogi, który przekonał Krąg Pradawnych na Mrocznym Wybrzeżu, że nadszedł czas, by nasz lud się odbudował i odzyskał nieśmiertelność.$B$BZa zgodą Kręgu Jeleniorogi wraz z najpotężniejszymi druidami wyhodował Teldrassil, nowe Drzewo Świata.', 0),
(934, 'plPL', 'Przebywać w obecności Drzewa Wyroczni... to niemal jak czuć, że mądrość przybiera kształt. Pozwól, że podejmę opowieść...$B$BGdy Teldrassil wyrósł, arcydruid zwrócił się do smoków o błogosławieństwo, takie, jakim niegdyś obdarzyły Nordrassil. Lecz Nozdormu, Władca Czasu, odmówił, ganiąc druida za pychę. Alexstraza przyznała Nozdormu rację i również odmówiła Jeleniorogiemu, a bez jej błogosławieństwa wzrost Teldrassilu jest wadliwy i nieprzewidywalny...', 0),
(935, 'plPL', 'Ach tak, woda, o którą prosiłem. Tenaron i Corithras nie spieszyli się z jej dostarczeniem... i chyba nie wybrali najrzetelniejszego posłańca... hmm.$B$BTak czy inaczej, mogę wreszcie wrócić do pracy. Ciężar problemów Teldrassilu spoczywa na moich barkach. To jarzmo, którego chciałbym się wkrótce pozbyć.$B$BWeź to, może ci się do czegoś przyda.', 0),
(937, 'plPL', 'Jestem pod wrażeniem tego, czego tu $gdokonałeś:dokonałaś; w tak krótkim czasie, $N. Chciałabym móc poprosić cię, byś $gzostał:została; i $gpomógł:pomogła; mi w moich obowiązkach... ale w głębi serca wiem, że czekają cię większe zadania.$b$bZauważyłam, że Drzewo Wyroczni właśnie zrzuciło kawałek kory. Bez wątpienia ma zadanie, które chce komuś powierzyć. Porozmawiaj z nim.', 0),
(938, 'plPL', 'Och, dziękuję ci, $N! Bałam się, że już nigdy nie zobaczę Mgiełki, że w sercu zostanie mi tylko myśl o jej śmierci i nigdy nie połączę się z moją wierną towarzyszką. Zawdzięczam ci więcej, niż możesz przypuszczać – masz moją wieczną wdzięczność.', 0),
(940, 'plPL', 'Zastanawiałem się, czemu Drzewo Wyroczni tak długo się do mnie nie odzywało... Wygląda na to, że jedne problemy maleją, a inne urastają do rangi poważniejszych zmartwień.$b$bObawiam się, że moja praca nad Teldrassilem nigdy nie zostanie ukończona, a nieśmiertelność nigdy nie zostanie nam przywrócona.$b$bTak czy inaczej, dobrze $gwykonałeś:wykonałaś; zadanie Drzewa Wyroczni i za swą sumienność zasługujesz na nagrodę.', 0),
(941, 'plPL', 'Umieszczasz serce w donicy, a ono szybko się w niej zakopuje!$b$bKilka sekund później wypełza z powrotem, oczyszczone. Lekko pulsuje... jakby prosiło, byś je $gzabrał:zabrała;.', 0),
(978, 'plPL', 'Teraz mogę porównać pióra... Zobaczmy...', 0),
(979, 'plPL', 'Cześć! Przysłał cię Erelas? Świetnie, właśnie szykowałam się do drogi do jaskiń i chętnie przyjmę towarzystwo.', 0),
(997, 'plPL', 'Ach, jest! Długo czekałem na tę rzadką ziemię. Mam nadzieję, że jest jeszcze świeża...$b$bDziękuję, że mi ją $gprzyniosłeś:przyniosłaś;, $N. Z ciebie $R, $gktóry:która; nie skąpi innym swojego czasu.', 0),
(1581, 'plPL', 'Są starannie sporządzone. Przykładasz wielką wagę do swojego rzemiosła, $N, a to dla alchemika ważne.$b$bOto twoje zioła, świeżo zebrane. Oby dobrze ci posłużyły.', 0),
(1684, 'plPL', 'Witaj, $N. Twoje imię głośno rozbrzmiewa w Darnassus, bo dobrze się zapowiadasz. Wkrótce jednak przekonamy się, czy masz dość siły woli, by podążać swoją ścieżką jako $c.', 0),
(2159, 'plPL', 'Ach tak, przesyłka ziół z Cienistego Jaru. Szkoda, że Porthannius nie mógł jej przynieść osobiście, bo wiele mamy sobie do omówienia. Mimo to cieszę się, że dostałem zioła, i cieszę się, że $gprzyszedłeś:przyszłaś;.$B$BSkoro już tu jesteś, proszę, odpocznij. Bohaterowie muszą dbać o siły i dobry nastrój, a odpoczynek i ukojenie powinni znajdować, kiedy tylko mogą. Zaniedbanie spokoju ciała i umysłu to pewna droga do porażki.$B$BWięc... odpocznij.', 0),
(2241, 'plPL', 'Gdybym zachowała każdy kwiat, jaki przysłał mi ten głupiec Jannok, mogłabym otworzyć kwiaciarnię. Tak czy inaczej, wygląda na to, że najnowszy posłaniec Jannoka może się do czegoś przydać. Interesuje cię trochę pracy, $N?', 0),
(2259, 'plPL', 'Czas rozwinąć skrzydła, $N – świat na ciebie czeka.', 0),
(2399, 'plPL', 'Liście paproci, które Denalan zasadził w swoim ogrodzie, wykiełkowały i urosły. Drżą, jakby nie mogły się doczekać, aż ktoś je zerwie...', 0),
(2438, 'plPL', 'Mój szmaragdowy łapacz snów jest dla mnie bardzo ważny. Taki dar otrzymują nieliczni. Dziękuję, że go $godzyskałeś:odzyskałaś;, $N.', 0),
(2459, 'plPL', 'Teraz mogę naprawić mój łapacz snów. Dziękuję, $N.', 0),
(2498, 'plPL', 'Ach, więc Rellian przysłał cię, byś mi $gpomógł:pomogła;. Cieszę się, że tak szybko tu $gdotarłeś:dotarłaś;.$b$bOdkryłem coś bardzo niepokojącego!', 0),
(2499, 'plPL', 'Wiedziałem, że bez trudu uwolnisz jezioro od tej okropnej bestii.$B$BTo przykra sprawa. Dębochmur był niegdyś wielkim przywódcą swojego gatunku... ale skażenie nie wybiera między maluczkimi a szlachetnymi.$B$BRozmiar tego guza jest naprawdę niepokojący, lecz muszę go zbadać, by dowiedzieć się więcej o chorobie, która dręczy drzewczyki.$B$BDziękuję ci, $N.', 0),
(2541, 'plPL', 'Dziękuję ci, $N.$b$bCóż za osobliwy przedmiot... Wyczuwam bijącą od niego plugawą aurę. To bardzo potężne zaklęcie.', 0),
(2561, 'plPL', 'Wreszcie jestem wolny od władzy plemienia Sękatej Sosny. Dziękuję ci, $N.$b$bMój duch może teraz na zawsze spocząć w spokoju w Szmaragdowym Śnie.$b$bByć może pewnego dnia znów się spotkamy. Ale na razie przyjmij, proszę, tę nagrodę jako wyraz mojej wdzięczności.', 0),
(2939, 'plPL', 'Ach, więc to Troyas Księżycowa Bryza cię przysłał?$b$b<mamrocze> ...ciągle mnie nachodzi ze swoimi szalonymi pomysłami, że znalazł coś ważnego...$b$bSłuchaj, $N, powiem wprost. Troyasowi zawsze się wydaje, że znalazł w tych ruinach coś ważnego. Prawda jest taka, że wszystko, co miało jakąkolwiek wartość, dawno temu zagarnęły pewnie ogry albo harpie, które teraz tam mieszkają.$b$bMożesz się tu rozejrzeć, ale nie wiem, czy znajdziesz jakieś księgi, które ci pomogą.', 0),
(2940, 'plPL', 'Więc chcesz pożyczyć „Feralas: historia”?$b$bNiech pomyślę...$b$bPozwolę ci pożyczyć tę księgę, $N, ale dopiero wtedy, gdy najpierw coś dla mnie zrobisz.', 0),
(2941, 'plPL', 'Też terminujesz u Daryn? To bardzo uczona historyczka, $N. Doceń to, że możesz się uczyć pod jej okiem.$b$bA teraz przyniosę Superpstrykacz FX. Pokochasz go!', 0),
(2943, 'plPL', '$GPrzyniosłeś:Przyniosłaś; księgę. Wspaniale!', 0),
(2944, 'plPL', 'No proszę! Wynalazek Curgle spełnił oczekiwania.$B$BTylko się za bardzo nie ekscytuj, ale wiedz, że jestem zadowolona z twojej pracy, $N.$B$BA teraz... gdzie ja położyłam tę księgę...', 0),
(3022, 'plPL', 'Dziękuję za pomoc, $N. Gdyby nie my, hipogryfy po prostu by się nie rozmnażały. Ach, ale z pewnością doskonale to rozumiesz, skoro $gbyłeś:byłaś; w Feralas i na własne oczy $gwidziałeś:widziałaś; spustoszenie, jakie sieją tam ogry Gordunni.$B$BCóż, jak widzisz, mam tu mnóstwo pracy, więc lepiej ruszaj w drogę.$B$BJeszcze raz dziękuję, $N.', 0),
(3116, 'plPL', 'Wkrótce ujrzysz wśród konarów naszego domu przybyszów z innych ras – nie pozwól, by zrodziło to w tobie uprzedzenia. Są tu mile widziani. Pomogą nam, gdy tylko będą mogli. Nie wszyscy będą bezinteresowni, ale należy obdarzyć ich pewną dozą zaufania.$b$bTeraz jednak nic z tego nie ma znaczenia. Teraz musimy skupić się na tobie i na tym, jak możesz pomóc naszemu ludowi. Właśnie po to tu jestem. W miarę jak będziesz rosnąć w siłę, będę cię uczyć wszystkiego, co musisz umieć jako $c. Wracaj do mnie, kiedy zechcesz, a zrobię, co w mojej mocy, by ci pomóc.', 0),
(3117, 'plPL', 'Gdy będziesz poznawać to, czego może cię nauczyć Cienisty Jar, przychodź do mnie – pomogę ci lepiej zrozumieć twoją rolę jako $c i to, do czego jesteś $gzdolny:zdolna;.$B$BNastały niebezpieczne czasy, $N. Doceniaj umiejętności swoich zwierząt – na tym świecie są rzeczy groźniejsze, niż możesz sobie wyobrazić. Idź z Eluną i wróć do mnie ponownie.', 0),
(3118, 'plPL', 'Do tego czasu wiedz, że w tych niepewnych czasach tacy jak my są potrzebni bardziej niż kiedykolwiek. Pokój z innymi rasami może upaść w każdej chwili, a wiele się mówi o tym, że członkowie Hordy chcą zasiać jeszcze więcej nieufności. Zapamiętaj to.$b$bGdy nabierzesz mocy i poczujesz się lepiej $gprzygotowany:przygotowana;, wróć tu do mnie, a zobaczę, czego mogę cię nauczyć. Musisz wiedzieć, jak posługiwać się wybraną bronią – i nie tylko.', 0),
(3119, 'plPL', 'Na razie nie przejmuj się światem pod Teldrassilem. Przyjdzie na to czas później. Idź teraz i porozmawiaj z pozostałymi w Cienistym Jarze – opowiedzą ci więcej o tym, co się wydarzyło. Pomagaj im, jak tylko możesz, a gdy poczujesz, że potrzebujesz dalszego szkolenia, wróć do mnie, a nauczę cię, czego zdołam.', 0),
(3120, 'plPL', 'Na razie będę twoim mentorem i przewodnikiem. Moim obowiązkiem jest nauczyć cię odczytywać nie tylko to, co przekazują nam duchy, ale też zawiłości i tajemnice Szmaragdowego Snu.$b$bW miarę jak będziesz się uczyć i rosnąć w siłę, dowiesz się więcej o naszym transie snu. Do tego czasu wracaj do mnie tak często, jak zechcesz, a nauczę cię, czego zdołam, o drogach naszego ludu.', 0),
(3519, 'plPL', 'Och, rety. Zastanawiałam się, czemu jeszcze dziś nie widziałam Iverrona. A tyle razy ostrzegałam go przed tymi pająkami...', 0),
(3521, 'plPL', 'Dzięki Elunie, że tak szybko $gzebrałeś:zebrałaś; te składniki!$b$bZa chwilę przygotuję odtrutkę.', 0),
(3522, 'plPL', 'Co to jest, $N?$b$bOch, wiedziałem, że Dirania zdoła mi pomóc!$b$b<Iverron wypija odtrutkę>$b$bCiągle pakuję się w kłopoty, a Dirania... cóż, zawsze jakoś mnie z nich wyciąga.$b$bCzuję się znacznie lepiej, ale chyba jeszcze tu chwilę posiedzę, aż całkiem dojdę do siebie. No i... miałem nadzieję, że utorujesz mi drogę przez te okrutne pająki z Pajęczego Lasu...', 0),
(3661, 'plPL', 'Dziękuję, że mi je $gprzyniosłeś:przyniosłaś;, $N.$B$BCzego się $gdowiedziałeś:dowiedziałaś; o dziczołakach?$B$BMoże te pióra powiedzą nam więcej. Groźne potwory czy po prostu zbłąkane pupile? Pewnego dnia chciałbym poznać prawdę...$B$BBędę kontynuował badania – wróć, proszę, i porozmawiaj ze mną znowu za jakiś czas.', 0),
(4161, 'plPL', 'Zawsze pamiętaj o tym, co ci dziś pokazałem, $N. Jesteś częścią równowagi, którą nocne elfy starają się zachować, nawet w trudnych czasach.', 0),
(4495, 'plPL', 'Tak się cieszę, że mnie $gznalazłeś:znalazłaś;, $N. Skąd $gwiedziałeś:wiedziałaś;, że tu jestem?', 0),
(4901, 'plPL', '$GSpotkałeś:Spotkałaś; się z Ranshallą?', 0),
(4902, 'plPL', 'Nie wahaj się – powiedz, z czym przychodzisz.$B$BOch, tak? Hm. No cóż.$B$BDziękuję, że z tym przychodzisz prosto do mnie; zawsze najlepiej zwracać się od razu na sam szczyt... Ale... Tak. Druidzi Kręgu Cenariona od pewnego czasu wiedzą o dziczołakach. O tym, że są pupilami Eluny i że wybrano je, by strzegły najświętszych miejsc.$B$BChoć nie jest to więc żadna nowina, z pewnością chwalę twój wysiłek. Proszę, weź to – wydaje się stosowną nagrodą za taki czyn.', 0),
(5250, 'plPL', '$GUczeń:Uczennica; Daryn Jasny Wiatr? Miło cię poznać, $N.', 0),
(5621, 'plPL', 'Dobrze się $gspisałeś:spisałaś; i $gprzysłużyłeś:przysłużyłaś; się Elunie. Za to ci dziękuję.$B$BProszę, przyjmij tę szatę w dowód mojej wdzięczności. Oznacza, że $gzasłużyłeś:zasłużyłaś; na miejsce w naszym zakonie. Jeśli zechcesz, noś ją z dumą, ale tak czy inaczej zawsze będziemy cię uważać za $gjednego:jedną; z nas.$B$BIdź z Eluną, $N, i dziękuję.', 0),
(5622, 'plPL', 'Cieszę się, że Shanda przysłała cię do mnie, $N. Nauczanie młodych kapłanów dróg Eluny daje mi wielką satysfakcję.', 0),
(6063, 'plPL', 'Świetnie, $N! Szybko się uczysz.', 0),
(6101, 'plPL', 'Widzę twoje zaangażowanie i to, że $gzrozumiałeś:zrozumiałaś;, czego cię nauczyłem, $N.', 0),
(6102, 'plPL', 'Nauczyłem cię wszystkiego, co mogłem, $N. Pozwól, że dam ci jeszcze jedną radę: rozważnie wybieraj swoje pierwsze zwierzę. Wybierzesz stworzenie lądu, wody czy nieba? Czymkolwiek będzie, bez wątpienia zostanie z tobą na długo.$B$BProszę, $N. Obdarzę cię teraz mocą oswajania bestii, a także przywoływania ich i odsyłania, gdy uznasz to za stosowne. Używaj nowych umiejętności z dumą – $gzasłużyłeś:zasłużyłaś; na nie.', 0),
(6103, 'plPL', '$GPoczątkujący:Początkująca; $c. Rozumiem. Tak. Mogę przekazać ci umiejętności potrzebne do szkolenia i prowadzenia twojego zwierzęcia. Nie tylko zdołasz uczyć je nowych zdolności – odtąd możesz je też karmić, a nawet wskrzesić, jeśli padnie w walce.$B$BPamiętaj, $N, zawsze szanuj równowagę i żyj w zachwycie nad otaczającą cię naturą. A teraz idź. Porozmawiamy znowu, w swoim czasie.', 0),
(6341, 'plPL', 'Ach, chcesz dostarczyć to do Auberdine? Dobrze więc...', 0),
(6342, 'plPL', 'Przesyłka od Nessy? Dziękuję, $N! Mówiła, że przyśle mi próbki ryb złowionych w pobliżu Wioski Rut\'theran. Uważa, że mogą się bardzo różnić od ryb łowionych tutaj...$b$bNo proszę! Ta szczęka jest prawie dwa razy większa niż u tej samej ryby stąd. A te łuski są wielkie jak zaciśnięta pięść! Niesamowite!', 0),
(6343, 'plPL', 'To bardzo ciekawe. Ryby są tu duże, ale nie sądziłam, że różnica między tutejszymi darami natury a tymi z lądu stałego jest aż tak wielka. Musi być jakiś powód...$B$BCóż, dziękuję ci, $N. Omówię z mieszkańcami wioski wieści, które $gprzyniosłeś:przyniosłaś;. Może pewnego dnia dotrzemy do korzeni tej osobliwości. A do tego czasu będziemy czerpać z niej korzyści!', 0),
(6344, 'plPL', 'Tak, potrzebuję posłańca, który zaniesie paczkę na Mroczne Wybrzeże. Pomożesz mi?', 0),
(7383, 'plPL', 'Przebywać w obecności Drzewa Wyroczni... to niemal jak czuć, że mądrość przybiera kształt. Pozwól, że podejmę opowieść...$B$BGdy Teldrassil już wyrósł, arcydruid zwrócił się do smoków o błogosławieństwo, takie jakim w dawnych czasach obdarzyły Nordrassil. Lecz Nozdormu, Pan Czasu, odmówił swego błogosławieństwa, strofując druida za jego arogancję. Zgadzając się z Nozdormu, także Alexstraza odmówiła Jeleniorogiemu, a bez jej błogosławieństwa wzrost Teldrassilu przebiega wadliwie i nieprzewidywalnie...', 0),
(8688, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8714, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8715, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8719, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8722, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8727, 'plPL', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8734, 'plPL', 'Wyciągnięcie Eranikusa ze Snu wbrew jego woli byłoby niemożliwe. Jego zamiary wymagają jednak, by wkroczył do naszego świata. Pragnie zniszczyć żywe wcielenie Malfuriona. Gdyby mu się to udało, oznaczałoby to koniec jednego z najpotężniejszych sprzymierzeńców Snu. Gdyby Malfurion upadł, Koszmar pochłonąłby bez reszty wszystko, co by pozostało...', 0),
(11753, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Teldrassilu!', 0),
(11824, 'plPL', 'Uczcij płomień Teldrassilu!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(456, 'plPL', 'Wciąż jest wiele do zrobienia, $N. Wróć do mnie, gdy przetrzebisz nocne szablobestie i ostowe dziki.', 0),
(457, 'plPL', 'Twoje zadanie nie zostało jeszcze wykonane, $N. Wróć do mnie, gdy zabijesz 5 parszywych nocnych szablobestii i 5 ostowych dzików.', 0),
(459, 'plPL', 'Sprawdź, czy moje podejrzenia są słuszne, $N. Przynieś mi 8 kęp spaczonego mchu.', 0),
(483, 'plPL', '$N, porwani druidzi Szponu zostaną na zawsze uwięzieni w Szmaragdowym Śnie, jeśli nie odzyskamy Relikwii Przebudzenia z Kurhanu Ban\'ethil na zachodzie.$b$bZ każdą minutą zwłoki ich los o krok przybliża się do wiecznej zguby.', 0),
(486, 'plPL', 'Naszych braci nie da się przebudzić, dopóki Ursal Szarpacz żyje, $N.', 0),
(487, 'plPL', 'Droga wciąż nie jest bezpieczna, $N. Wyrusz, zabij 6 napastników Sękatej Sosny i wróć do mnie.', 0),
(488, 'plPL', '$GByłeś:Byłaś; pracowitą pszczółką, $N? Czekam, aż przyniesiesz mi to, czego potrzebuję.', 0),
(489, 'plPL', 'Co tam dla mnie masz, $N? Pewnie jakąś pyszną przekąskę?', 0),
(493, 'plPL', 'Masz coś dla mnie?', 0),
(916, 'plPL', '$GZebrałeś:Zebrałaś; gruczoły jadowe, $N?', 0),
(917, 'plPL', '$GByłeś:Byłaś; w Jaskini Cienistej Nici, $N? $GZnalazłeś:Znalazłaś; pajęcze jajo?', 0),
(918, 'plPL', 'Masz nasiona? Nie mogę się doczekać, żeby je zasadzić.', 0),
(919, 'plPL', 'Witaj, $N. $GZnalazłeś:Znalazłaś; jakieś kiełki nad wodą?', 0),
(921, 'plPL', 'Księżycowe studnie kryją wody Studni Wieczności – pradawnego źródła magii, które sprowadziło na nasz świat tak wiele okropieństw.$B$BDruidzi korzystają z ich właściwości, a Strażniczki czczą studnie jako świątynie Eluny, lecz czary są zakazane dla wszystkich.', 0),
(922, 'plPL', 'Witaj...$b$bW czym mogę ci pomóc?', 0),
(923, 'plPL', '$GByłeś:Byłaś; nad Jeziorem Źródlanym, $N? $GPolowałeś:Polowałaś; tam na drzewczyki?', 0),
(927, 'plPL', '$N! Masz coś dla mnie?', 0),
(928, 'plPL', 'Witaj, $N. Czemu zawdzięczam przyjemność tego spotkania?', 0),
(929, 'plPL', 'Witaj ponownie, $N. $GWykonałeś:Wykonałaś; zadanie?', 0),
(930, 'plPL', '$N, wyglądasz, jakbyś $gmiał:miała; mi coś do powiedzenia. Masz wieści o drzewczykach?', 0),
(931, 'plPL', 'Masz coś dla mnie?', 0),
(932, 'plPL', '$GZabiłeś:Zabiłaś; już lorda Melenasa? Trzeba się nim zająć szybko i po cichu, $N. Samo jego istnienie przynosi wstyd nam wszystkim.', 0),
(933, 'plPL', 'Z początku lekceważono doniesienia o atakach oszalałych furbolgów. Któż by pomyślał, że miłujący pokój niedźwiedziolud popadnie w bezmyślny szał? To kolejny z problemów, które nękają nas w naszym nowym domu.', 0),
(934, 'plPL', 'Wraz z druidami Drzewo Wyroczni i arcydruid uważnie śledzą wzrost Teldrassilu. Lecz choć mamy nowy dom, nie odzyskaliśmy nieśmiertelności.', 0),
(935, 'plPL', 'Wiem, że cię nie wzywałem, więc zastanawiam się, dlaczego $gprzyszedłeś:przyszłaś; ze mną porozmawiać.$B$BCokolwiek to jest, proszę, streszczaj się.', 0),
(937, 'plPL', 'Ich tnące szpony i przeszywające dzioby mogą okazać się groźnym wyzwaniem dla twoich umiejętności, $N, ale wierzę, że nie zawiedziesz w tym zadaniu.', 0),
(938, 'plPL', 'Mgiełko... To moja wina! Wiedźmy mnie zaskoczyły... Nie powinnam była pozwolić, by cię zabrały...', 0),
(940, 'plPL', 'Hmm... Silny duch lasu przychodzi tu razem z tobą, $N. Jaką sprawę masz do arcydruida kaldorei?', 0),
(941, 'plPL', 'Ta donica jest pełna gleby specjalnie przygotowanej przez Denalana.', 0),
(978, 'plPL', 'Skąd mogły się wziąć te moce? Myślę, że jesteśmy na dobrym tropie, $N.', 0),
(997, 'plPL', 'Masz coś dla mnie?', 0),
(1220, 'plPL', 'Masz coś dla mnie?', 0),
(1238, 'plPL', 'Masz coś dla mnie?', 0),
(1359, 'plPL', 'Masz coś dla mnie?', 0),
(1423, 'plPL', 'Masz coś dla mnie?', 0),
(1581, 'plPL', 'Witaj, $N. Masz eliksiry na wymianę?', 0),
(2159, 'plPL', 'Czym mogę ci służyć, $gmój młody przyjacielu:moja młoda przyjaciółko;? Chcesz odpocząć w gospodzie? Potrzebujesz Kamienia Powrotu?', 0),
(2241, 'plPL', 'Och, czyż to nie cudowne? $GPrzyniosłeś:Przyniosłaś; kwiaty na własny pogrzeb.', 0),
(2438, 'plPL', 'Proszę, pospiesz się. Mogę tylko mieć nadzieję, że furbolgi nie uszkodziły mojego szmaragdowego łapacza snów.$b$b$GOdzyskałeś:Odzyskałaś; go już, $N?', 0),
(2459, 'plPL', 'Ferocitas i mistycy Sękatej Sosny muszą oddać to, co moje. Proszę, odzyskaj szmaragd, żebym mógł naprawić mój szmaragdowy łapacz snów.', 0),
(2499, 'plPL', 'Czy $gznalazłeś:znalazłaś; już Dębochmura?', 0),
(2541, 'plPL', 'Jeśli zbadam ten amulet, może zdołam odkryć, jak przełamać zaklęcie. $GZnalazłeś:Znalazłaś; jakiś?', 0),
(2561, 'plPL', '$N, zachowaj ostrożność, gdy będziesz zbliżać się do mojego ciała. Ciąży na nim bardzo potężne zaklęcie.', 0),
(2941, 'plPL', 'List? Do mnie?', 0),
(2943, 'plPL', 'Witaj, $N. $GByłeś:Byłaś; w Darnassus?', 0),
(2944, 'plPL', 'A więc wreszcie $gwróciłeś:wróciłaś;, $N. I $gprzyniosłeś:przyniosłaś; urządzenie, które zbudowała dla mnie Curgle. Doskonale.', 0),
(3022, 'plPL', 'Kolejna dostawa od Curgle, jak mniemam?', 0),
(3116, 'plPL', 'Udało ci się. Tak się cieszę.$b$bWiele się wydarzyło w ciągu ostatnich kilku lat, $N: powstanie Teldrassilu, skażenie wielu leśnych stworzeń tu i w innych krainach, odkrycie ziem, które uważaliśmy za utracone, takich jak Feralas... tak wiele w tak krótkim czasie. Ale to tylko niektóre z powodów, dla których tu jesteśmy – najważniejszym jest ochrona naszego ludu przed kolejnym złem.', 0),
(3117, 'plPL', '$GPrzybyłeś:Przybyłaś;, i to w samą porę, $N. Witaj w Cienistym Jarze.$B$BMam nadzieję, że mój symbol zastał cię w dobrym zdrowiu i nastroju?$B$BJak już wspominałam, jestem tu, by cię szkolić – jako $C musisz umieć oswajać bestie, które wesprą cię w walce, władać łukiem z niezawodną celnością, szanować ziemie, które nazywamy domem, a także te, które leżą dalej.', 0),
(3118, 'plPL', 'Witaj, $n. Cieszę się, że mnie $gznalazłeś:znalazłaś;. Już myślałem, że $gzgubiłeś:zgubiłaś; drogę.$B$BOd kiedy wysłałem ci symbol, w Cienistym Jarze nie wydarzyło się nic nowego, ale zbieranie informacji zostawię tobie. Jeśli chcesz, porozmawiaj z innymi wokół Aldrassilu.', 0),
(3119, 'plPL', 'Cieszę się, że $gprzybyłeś:przybyłaś; tak szybko, $N. Witaj.$b$bJak pewnie $gsłyszałeś:słyszałaś;, cały Teldrassil tętni życiem za sprawą przybywających i odchodzących podróżnych. Nawet członkom Przymierza pozwolono wstąpić na konary Teldrassilu, by mogli spotkać się z innymi kaldorei, którzy szykują się na czekające ich przygody.', 0),
(3120, 'plPL', 'Ach, $N. Widzę, że chętnie kontynuujesz naukę. To dobrze.$b$bZastanawiam się, czy $gspędziłeś:spędziłaś; już dużo czasu w Szmaragdowym Śnie? Może nie jesteś jeszcze na to $ggotowy:gotowa;... Z czasem na pewno będziesz.$b$bAle do tego czasu powinniśmy pomówić o innych sprawach.', 0),
(3521, 'plPL', 'Proszę, zbierz składniki, $N. Iverron potrzebuje naszej pomocy.', 0),
(3522, 'plPL', 'Och... $N, tak się cieszę, że $gwróciłeś:wróciłaś;.', 0),
(3661, 'plPL', 'Jeśli możesz, unikaj ich, $N. Dziczołaki mogą wziąć twoje zainteresowanie za chęć zrobienia im krzywdy...', 0),
(4161, 'plPL', 'Pamiętaj o równowadze, $N. Pragnę, by zrodziło się w tobie zrozumienie i głęboka empatia wobec żyjących lasów.', 0),
(5621, 'plPL', 'Nasze czary wzmacniające są bardzo potężne, Delor. Pozwalają naszym towarzyszom znieść więcej obrażeń od wszelkich ataków i przetrwać sytuacje, w których normalnie by polegli. Ale to nic w porównaniu z naszą zdolnością leczenia. Nie ma większych uzdrowicieli niż kapłani – dobrze to zapamiętaj. Sama twoja moc potrafi z łatwością odwrócić losy bitwy.', 0),
(6063, 'plPL', 'Nauczysz się, $N, i pewnego dnia $gzostaniesz wielkim łowcą:zostaniesz wielką łowczynią;.', 0),
(6101, 'plPL', 'Zrozumienie równowagi między naturą a samym sobą to sposób życia dla każdego z nas.', 0),
(6102, 'plPL', 'Jestem dumny z twoich osiągnięć, $N. $GUkończyłeś:Ukończyłaś; ostatnie zadanie, które ci dałem?', 0),
(6341, 'plPL', 'W czym mogę pomóc? Potrzebujesz transportu?', 0),
(6342, 'plPL', 'Przybywasz z Teldrassilu? Powiedz, jak tam biorą ryby?', 0),
(6343, 'plPL', '$N, $gwróciłeś:wróciłaś; z Auberdine? $GRozmawiałeś:Rozmawiałaś; z Lairdem?', 0),
(7383, 'plPL', 'Wraz z druidami Drzewo Wyroczni i arcydruid uważnie śledzą wzrost Teldrassilu. Lecz choć mamy nowy dom, nie odzyskaliśmy nieśmiertelności.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2080, 0, 'plPL', 'Stworzenie Teldrassilu było wielkim osiągnięciem, lecz teraz świat musi się przestawić, by odzyskać równowagę.', 0),
(3519, 0, 'plPL', 'Ja, Arynia Rozdarta Chmura, otrzymałam zadanie strzeżenia świętości Polany Wyroczni.', 0),
(3567, 0, 'plPL', 'Witaj, $n. Dobrze widzieć, że tacy jak ty biorą czynny udział w ochronie gajów.', 0);
