INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1156, 'plPL', 'Curgle,$B$Bz niecierpliwością czekam na twój najnowszy wynalazek. Nie mogę się doczekać, aż zacznę go używać do dokumentowania moich badań.$B$BPowierz go, proszę, mojemu posłańcowi.$B$B$BZ najserdeczniejszymi pozdrowieniami$B$BDaryn Jasny Wiatr', 0),
(1171, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\9330_Gammerita_sepia_256"/>\n</BODY>\n</HTML>', 0),
(1190, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\9330_Gammerita_sepia_256"/>\n</BODY>\n</HTML>', 0),
(2437, 'plPL', 'Sael\'ah, $gprzyjacielu:przyjaciółko;. Mam nadzieję, że ten znak zastaje cię w dobrym zdrowiu. Poproszono mnie, bym zaoferował ci swoje usługi. Ja również przebywam w Cienistym Jarze, w wielkim drzewie Aldrassil, i chciałem, żebyś $gwiedział:wiedziała;, że jeśli potrzebujesz szkolenia, możesz mnie odszukać.$B$BW tych niepewnych czasach uznałem za rozsądne, by ci, którzy parają się skrytością, trzymali się jeszcze bliżej siebie. Jak inaczej moglibyśmy chronić Teldrassil i nasze obyczaje?$B$BOdszukaj mnie, gdy tylko $gbędziesz mógł:będziesz mogła;.$B$B– Frahun Szept Cienia, nauczyciel łotrów', 0),
(2444, 'plPL', 'Mam nadzieję, że mój znak zastaje cię w dobrym zdrowiu, $N. Piszę do ciebie, ponieważ nasz lud potrzebuje tych, którzy są silni ostrzem, glewią i wszelką inną bronią. Od czasu, gdy nasz lud na nowo zetknął się z innymi rasami Azeroth, wydarzyło się tak wiele, że jeszcze bardziej potrzebujemy obrońców wszelkiego rodzaju.$B$BI tu wkraczasz ty. Powiedziałabym więcej, ale czuję, że lepiej zrobić to osobiście. Odszukaj mnie w Aldrassilu... na niższych poziomach.$B$B– Alyissia, nauczycielka wojowników', 0),
(2456, 'plPL', 'Elune jest z tobą, $N. Szepcze mi to wiatr i cieszę się, że mogę bezpośrednio uczestniczyć w kształtowaniu naszego nowego pokolenia łowców.$B$BZ tego, co mi powiedziano, jesteś niedaleko Aldrassilu. Chętnie spotkam się z tobą we wnętrzu wielkiego drzewa, gdy znajdziesz czas.$B$BStarszyzna powierzyła mi zadanie dopilnowania, by nowi łowcy byli właściwie przygotowani na czekające ich próby. Jako że należysz do najnowszych uczniów, dobrze byłoby, gdybyś mnie $godwiedził:odwiedziła;. Do tego czasu $gbądź zdrów:bądź zdrowa;.$B$B– Ayanna Wiecznokroka, nauczycielka łowców', 0),
(2459, 'plPL', 'Gdy dotarła do mnie wieść, że jesteś $ggotów:gotowa;, od razu wysłałem ten znak. Wszyscy druidzi Cenariusa z wielką radością patrzą, jak rosną nasze szeregi. Nawet duchy zdają się silniejsze, odkąd jest nas więcej. Z czasem i przy odrobinie cierpliwości nasza siła, miejmy nadzieję, odzyska dawną świetność. Odszukaj mnie w pobliżu szczytu Aldrassilu, gdy będziesz $ggotów:gotowa;. Będę twoim przewodnikiem, dopóki przebywasz w Cienistym Jarze.$B$B– Mardant Mocny Dąb, nauczyciel druidów', 0),
(2468, 'plPL', 'Mam nadzieję, że ten znak zastaje cię w dobrym zdrowiu, $N. Duchy powiedziały mi o twoim przybyciu, więc od razu przesłałam wiadomość. Z radością podzielę się z tobą swoim doświadczeniem i pomogę ci przygotować się do opuszczenia Teldrassilu dla ważniejszych spraw.$B$BPo wszystkim, co wydarzyło się w ostatnich latach, wiele możemy zrobić, by wesprzeć inne rasy Azeroth. Gdy będziesz $ggotów:gotowa;, odszukaj mnie w Aldrassilu, na drugim poziomie.$B$B– Shanda, nauczycielka kapłanów', 0),
(2513, 'plPL', 'Nesso,$B$Bdobrze mieć od ciebie wieści.$B$BZbiór ości i łusek, który mi przysłałaś, był niesamowity. Nigdy nie widziałem ryb takich rozmiarów u wybrzeży lądu. Rybacy z Rut\'theran muszą wyciągać bez trudu tonę ryb dziennie!$B$BZazdroszczę im tak obfitych połowów, ale też odrobinę mnie to niepokoi. Czyżby to nasze nowe drzewo świata sprawiało, że ryby tak rosną? Jeśli tak, jakie jeszcze może mieć skutki?$B$BPytania do rozważenia,$B– Laird', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(15906, 'plPL', 'Na górnym poziomie Świątyni Księżyca znajdziesz dwoje draenei, którzy rozmawiają z Tyrande Szept Wiatru.$B$BOni będą wiedzieć, jak ci pomóc.', 'Na górnym poziomie Świątyni Księżyca znajdziesz dwoje draenei, którzy rozmawiają z Tyrande Szept Wiatru.$B$BOni będą wiedzieć, jak ci pomóc.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50032, 'plPL', 'Bądź $gpozdrowiony:pozdrowiona;, $N. Dobrze widzieć, że tacy jak ty biorą czynny udział w ochronie gajów.', 'Bądź $gpozdrowiony:pozdrowiona;, $N. Dobrze widzieć, że tacy jak ty biorą czynny udział w ochronie gajów.', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
