INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(886, 'plPL', 'Kum! Nie!! To nie może... kum... być! $GOszukałeś:Oszukałaś; mnie... kum... swoimi plugawymi sztuczkami! Kum!', '', 0),
(888, 'plPL', 'Koszmar Ursala dobiegł końca! Jesteśmy wolni!', '', 0),
(1126, 'plPL', '%s bada Serce oplecione mchem...', '', 0),
(1127, 'plPL', '$n, pod tym mchem to serce wygląda jak nasiono!', '', 0),
(1128, 'plPL', 'Spróbujmy zasadzić je w mojej specjalnie przygotowanej glebie...', '', 0),
(1156, 'plPL', '%s wyjmuje nasiona ze Świecącego owocu...', '', 0),
(1157, 'plPL', 'Zobaczmy, jak te nasiona wyrosną w mojej przygotowanej glebie...', '', 0),
(1158, 'plPL', '%s sadzi nasiona owocu.', '', 0),
(1159, 'plPL', '%s spieszy do swojej donicy.', '', 0),
(1160, 'plPL', 'Oby ten liść się zakorzenił...', '', 0),
(1239, 'plPL', 'A teraz umieśćmy tę rzadką ziemię w mojej donicy...', '', 0),
(1240, 'plPL', 'Jeszcze raz dziękuję, $n. Ta rzadka ziemia bardzo mi się przyda w moich doświadczeniach.', '', 0),
(1330, 'plPL', '', 'Mgiełko! Bałam się, że już nigdy cię nie zobaczę! Tak, nic mi nie jest, nie martw się o mnie. Musisz odpocząć i odzyskać siły.', 0),
(1340, 'plPL', '%s warczy na znak zrozumienia, po czym prostuje się i odchodzi w głąb lasu.', '', 0),
(2229, 'plPL', '', 'Twoja głowa będzie pięknym trofeum, $N.', 0),
(2230, 'plPL', '', 'Moje szpony rozszarpią twoje wątłe ciało, $N.', 0),
(2231, 'plPL', '', 'Będziesz łatwą zdobyczą, $N.', 0),
(2827, 'plPL', 'Twoje ciało wygląda na wyczerpane, a duch na znużony. Odpocznij pod naszym dachem i pozwól, by Elune prowadziła twoje sny.', 'Twoje ciało wygląda na wyczerpane, a duch na znużony. Odpocznij pod naszym dachem i pozwól, by Elune prowadziła twoje sny.', 0),
(2977, 'plPL', 'Jak kot wciągnięty z deszczu, drapiesz i szarpiesz, a potem znów od nowa... Jeszcze tu wrócę...$B$BOch, nie zauważyłem, jak $gwszedłeś:weszłaś;, $n! Co mogę dla ciebie zrobić?', 'Jak kot wciągnięty z deszczu, drapiesz i szarpiesz, a potem znów od nowa... Jeszcze tu wrócę...$B$BOch, nie zauważyłem, jak $gwszedłeś:weszłaś;, $n! Co mogę dla ciebie zrobić?', 0),
(2978, 'plPL', 'Witaj! Jestem $głotrem:łotrzycą; i potrzebuję szkolenia.', 'Witaj! Jestem $głotrem:łotrzycą; i potrzebuję szkolenia.', 0),
(2981, 'plPL', 'Wiem, że tu jesteś, łotrze. Opuść mój dom albo dołącz do pozostałych u stóp drzewa świata.', '', 0),
(2982, 'plPL', 'Nadchodzi koniec dni! Niech ziemia przyjmie moje ciało i kości.', '', 0),
(3001, 'plPL', 'Plugastwo! Wszędzie plugastwo! Lasy muszą zostać oczyszczone!', '', 0),
(3002, 'plPL', 'To beznadziejne. Gdy zetniesz jeden, wyrastają dwa nowe.', '', 0),
(3162, 'plPL', 'To egzotyczny okaz roślinności, niespotykany w innych częściach Teldrassilu.', '', 0),
(3163, 'plPL', 'Ta roślina wyróżnia się spośród zwykłej flory Teldrassilu i emanuje dziwnym, purpurowym blaskiem.', '', 0),
(3813, 'plPL', '', 'Witaj! Mam propozycję dla kogoś, kto szuka przygód tak jak ty – jeśli tylko podołasz wyzwaniu!$B$BWraz z moim wynalazkiem, Super Jajomatem, ciężko pracuję, pomagając druidom w ich kampanii na rzecz ocalenia hipogryfów. Na te ptaki źle wpływa zło ogrów Gordunni, które zamieszkują ruiny Feralas, i jest ich coraz mniej.$B$BZbieram wiele różnych rodzajów jaj. Pomożesz mi i znajdziesz dla mnie kilka?', 0),
(3814, 'plPL', 'Opowiedz mi więcej o hipogryfach.', 'Opowiedz mi więcej o hipogryfach.', 0),
(3815, 'plPL', '', 'W krainie zwanej Feralas, na zachód stąd, hipogryfom – odwiecznym towarzyszom nocnych elfów – grozi niebezpieczeństwo.$B$BMusisz ocalić jajo z tamtejszych Ruin Isildien, na południu. Super Jajomat potrafi zbadać każde przyniesione jajo i ocenić, czy coś się z niego wykluje. Potem wysyłam jaja druidom, z dala od mrocznej magii ogrów Gordunni.$B$BPamiętaj jednak, $n, że część ocalonych jaj to zbuki, z których nic się nie wykluje.', 0),
(3923, 'plPL', 'Opowiedz mi więcej o ograch Gordunni.', 'Opowiedz mi więcej o ograch Gordunni.', 0),
(3924, 'plPL', '', 'Gordunni to duże plemię ogrów, które panuje nad sporą częścią lasów Feralas. Ich mroczna magia przesącza się do otaczających je żywiołów, niszcząc zarówno przyrodę, jak i zamieszkujące ją stworzenia.$B$BJeśli zdecydujesz się wyruszyć do Feralas, uważaj na te ogry – są naprawdę paskudne, a wiele z nich włada potężną mroczną magią.', 0),
(4039, 'plPL', '„Feralas: historia”... Hmmm... Pozwól, że przez chwilę się temu przyjrzę.', '', 0),
(4040, 'plPL', '%s przegląda pobieżnie strony księgi.', '', 0),
(4041, 'plPL', 'Niesamowite! Chyba to znalazłem, $n!', '', 0),
(4042, 'plPL', '', 'Rozejrzyj się, $n. Może znajdziesz coś, co mi umknęło.', 0),
(4043, 'plPL', '', '%s wskazuje na stosy ksiąg.', 0),
(4562, 'plPL', 'Strażniczki, do mnie! Brońcie mnie!', 'Strażniczki, do mnie! Brońcie mnie!', 0),
(4572, 'plPL', 'Witaj, $n. Szkolę tu młode hipogryfy i się nimi opiekuję. Rozejrzyj się śmiało.', '', 0),
(4573, 'plPL', 'Opowiedz mi więcej o tych hipogryfach.', 'Opowiedz mi więcej o tych hipogryfach.', 0),
(4574, 'plPL', 'Druidów bardzo porusza dola wszystkich stworzeń tego świata. Gdy okazało się, że tym ptakom grozi niebezpieczeństwo, stworzyliśmy sposób, by ratować je przed skażeniem Feralas.$B$BCałym przedsięwzięciem kieruje gnomka imieniem Curgle Cranklehop – to ona zbiera jaja i wysyła je tutaj, a ja się nimi opiekuję.$B$BNaszej sprawie zawsze przyda się więcej pomocy, $n. Może wybierzesz się do Gadżetonu i odszukasz Curgle?', '', 0),
(4888, 'plPL', 'Bank', 'Bank', 0),
(4988, 'plPL', 'Chcę się uczyć gotowania.', 'Chcę się uczyć gotowania.', 0),
(4989, 'plPL', 'Witaj, $n. Jeśli chcesz się czegoś dowiedzieć o gotowaniu, odwiedź mnie, kiedy tylko zechcesz.', '', 0),
(5325, 'plPL', 'Które z cudownych miejsc Darnassus mam ci wskazać?', 'Które z cudownych miejsc Darnassus mam ci wskazać?', 0),
(5329, 'plPL', 'Swoje ziemskie dobra możesz przechować w banku Darnassus, który leży w samym sercu naszego wspaniałego miasta.', 'Swoje ziemskie dobra możesz przechować w banku Darnassus, który leży w samym sercu naszego wspaniałego miasta.', 0),
(5331, 'plPL', 'Hipogryfy Vesprystusa szybko zaniosą cię do celu. Szukaj go w Wiosce Rut\'theran – dotrzesz tam przez portal w zachodniej części Darnassus.', 'Hipogryfy Vesprystusa szybko zaniosą cię do celu. Szukaj go w Wiosce Rut\'theran – dotrzesz tam przez portal w zachodniej części Darnassus.', 0),
(5333, 'plPL', 'Jeśli chcesz założyć bractwo, musisz udać się do mistrzyni gildii, Lysheany. Znajdziesz ją na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 'Jeśli chcesz założyć bractwo, musisz udać się do mistrzyni gildii, Lysheany. Znajdziesz ją na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 0),
(5335, 'plPL', 'Choć dla mnie chłodna trawa porastająca Teldrassil jest równie dobrym posłaniem jak każde inne, łóżka, o które dba Saelienne w karczmie na Tarasie Rzemieślników, w zupełności zadowolą tych, którzy gustują w wygodach.', 'Choć dla mnie chłodna trawa porastająca Teldrassil jest równie dobrym posłaniem jak każde inne, łóżka, o które dba Saelienne w karczmie na Tarasie Rzemieślników, w zupełności zadowolą tych, którzy gustują w wygodach.', 0),
(5337, 'plPL', 'Przed bankiem, który znajdziesz w centrum Darnassus, stoi skrzynka pocztowa.', 'Przed bankiem, który znajdziesz w centrum Darnassus, stoi skrzynka pocztowa.', 0),
(5339, 'plPL', 'Tu, w Darnassus, znajdziesz biegłych nauczycieli, którzy przez całe wieki ćwiczeń i poświęcenia doprowadzili do perfekcji umiejętności swojej klasy. Wskażę ci kogoś, kto może zostać twoim mistrzem – wystarczy, że wymienisz wybraną przez siebie ścieżkę.', 'Tu, w Darnassus, znajdziesz biegłych nauczycieli, którzy przez całe wieki ćwiczeń i poświęcenia doprowadzili do perfekcji umiejętności swojej klasy. Wskażę ci kogoś, kto może zostać twoim mistrzem – wystarczy, że wymienisz wybraną przez siebie ścieżkę.', 0),
(5341, 'plPL', 'Masz szczęście, że $gtrafiłeś:trafiłaś; do Darnassus, gdzie wśród naszych nauczycieli jest tak znakomita łowczyni jak Jocaste. Zachęcam cię, byś $godwiedził:odwiedziła; ją w Enklawie Cenariona i $gposzedł:poszła; do niej na naukę.', 'Masz szczęście, że $gtrafiłeś:trafiłaś; do Darnassus, gdzie wśród naszych nauczycieli jest tak znakomita łowczyni jak Jocaste. Zachęcam cię, byś $godwiedził:odwiedziła; ją w Enklawie Cenariona i $gposzedł:poszła; do niej na naukę.', 0),
(5343, 'plPL', 'W ponurych czasach druid bywa drogim przyjacielem dla wszystkich wokół. Zapytaj któregokolwiek z druidów w Enklawie Cenariona, a powie ci to samo.', 'W ponurych czasach druid bywa drogim przyjacielem dla wszystkich wokół. Zapytaj któregokolwiek z druidów w Enklawie Cenariona, a powie ci to samo.', 0),
(5345, 'plPL', 'Świątynia Księżyca jest domem kapłanów Eluny. Znajdziesz tam Jandrię i Lariię, które poprowadzą cię dalej ścieżką kapłaństwa.', 'Świątynia Księżyca jest domem kapłanów Eluny. Znajdziesz tam Jandrię i Lariię, które poprowadzą cię dalej ścieżką kapłaństwa.', 0),
(5346, 'plPL', 'Moc Eluny cię wzywa! Moc Eluny cię wzywa!\nIdź już! Odszukaj Jandrię w głównej sali Świątyni Księżyca w południowej części Darnassus!', 'Moc Eluny cię wzywa! Moc Eluny cię wzywa!\nIdź już! Odszukaj Jandrię w głównej sali Świątyni Księżyca w południowej części Darnassus!', 0),
(5348, 'plPL', 'Jeśli chcesz podążać ścieżką łotra, szukaj Syurny. Przebywa w Enklawie Cenariona – zejdź krętą ścieżką we wnętrzu najbardziej wysuniętego na zachód drzewa.', 'Jeśli chcesz podążać ścieżką łotra, szukaj Syurny. Przebywa w Enklawie Cenariona – zejdź krętą ścieżką we wnętrzu najbardziej wysuniętego na zachód drzewa.', 0),
(5349, 'plPL', 'Są tacy, którzy próbują podążać ścieżką łotra, ale tylko nocne elfy noc naprawdę bierze w objęcia. Jeśli chcesz kroczyć ścieżką cienia, odszukaj Syurnę w Enklawie Cenariona.', 'Są tacy, którzy próbują podążać ścieżką łotra, ale tylko nocne elfy noc naprawdę bierze w objęcia. Jeśli chcesz kroczyć ścieżką cienia, odszukaj Syurnę w Enklawie Cenariona.', 0),
(5351, 'plPL', 'Sildinair znajdziesz na Tarasie Wojowników pośród strażników – jej bystre oczy przeczesują las w poszukiwaniu wrogów, którzy mogliby się odważyć wtargnąć do naszego pięknego miasta.', 'Sildinair znajdziesz na Tarasie Wojowników pośród strażników – jej bystre oczy przeczesują las w poszukiwaniu wrogów, którzy mogliby się odważyć wtargnąć do naszego pięknego miasta.', 0),
(5353, 'plPL', 'Tu, wśród rzemieślników Darnassus, czeka na ciebie tysiąc lat wiedzy, która przysłuży się wybranemu przez ciebie rzemiosłu. Powiedz mi zatem, które rzemiosło najbardziej cię zaciekawiło?', 'Tu, wśród rzemieślników Darnassus, czeka na ciebie tysiąc lat wiedzy, która przysłuży się wybranemu przez ciebie rzemiosłu. Powiedz mi zatem, które rzemiosło najbardziej cię zaciekawiło?', 0),
(5355, 'plPL', 'Jeśli naprawdę pragniesz nauczyć się tej profesji, skieruję cię do Ainethil, biegłej alchemiczki z Tarasu Rzemieślników w północnej części Darnassus.', 'Jeśli naprawdę pragniesz nauczyć się tej profesji, skieruję cię do Ainethil, biegłej alchemiczki z Tarasu Rzemieślników w północnej części Darnassus.', 0),
(5357, 'plPL', 'Alegorn to mistrz kuchni, który miał całe stulecia, by udoskonalić swoją sztukę. Uważaj się za $gszczęśliwca:szczęściarę;, jeśli zdecyduje się cię uczyć. Jeśli uważasz, że jesteś tego $ggodzien:godna;, znajdziesz go na Tarasie Rzemieślników.', 'Alegorn to mistrz kuchni, który miał całe stulecia, by udoskonalić swoją sztukę. Uważaj się za $gszczęśliwca:szczęściarę;, jeśli zdecyduje się cię uczyć. Jeśli uważasz, że jesteś tego $ggodzien:godna;, znajdziesz go na Tarasie Rzemieślników.', 0),
(5358, 'plPL', 'Potrawy, które wyczarowuje Alegorn, są po prostu niebiańskie. Wiecznie przyrządza nowe przysmaki na Tarasie Rzemieślników. Koniecznie spróbuj jego cenariońskiej zieleniny, jeśli jeszcze coś mu zostało.\nA teraz wybacz, muszę zbadać tę falę zaginięć jeleni.', 'Potrawy, które wyczarowuje Alegorn, są po prostu niebiańskie. Wiecznie przyrządza nowe przysmaki na Tarasie Rzemieślników. Koniecznie spróbuj jego cenariońskiej zieleniny, jeśli jeszcze coś mu zostało.\nA teraz wybacz, muszę zbadać tę falę zaginięć jeleni.', 0),
(5364, 'plPL', 'Ponieważ ostrze nigdy nie jest zbyt ostre, a zbroja nigdy zbyt wytrzymała, utalentowany zaklinacz zawsze będzie potrzebny. Takim zaklinaczem jest Taladan, który nauczy cię, jak właściwie splatać zaklęcia, by ulepszać broń i zbroję. Szukaj go na Tarasie Rzemieślników.', 'Ponieważ ostrze nigdy nie jest zbyt ostre, a zbroja nigdy zbyt wytrzymała, utalentowany zaklinacz zawsze będzie potrzebny. Takim zaklinaczem jest Taladan, który nauczy cię, jak właściwie splatać zaklęcia, by ulepszać broń i zbroję. Szukaj go na Tarasie Rzemieślników.', 0),
(5367, 'plPL', 'Kiedy nie ma przy tobie uzdrowiciela, który opatrzy ci rany, znajomość pierwszej pomocy może uratować życie. Po naukę tej umiejętności udałabym się do Dannelora na Tarasie Rzemieślników.', 'Kiedy nie ma przy tobie uzdrowiciela, który opatrzy ci rany, znajomość pierwszej pomocy może uratować życie. Po naukę tej umiejętności udałabym się do Dannelora na Tarasie Rzemieślników.', 0),
(5369, 'plPL', 'To czasochłonna, ale satysfakcjonująca umiejętność. Porozmawiaj z Astaią na Tarasie Kupców, a może nauczysz się czegoś przydatnego.', 'To czasochłonna, ale satysfakcjonująca umiejętność. Porozmawiaj z Astaią na Tarasie Kupców, a może nauczysz się czegoś przydatnego.', 0),
(5372, 'plPL', 'Kunszt, z jakim Telonis wytwarza zbroje, nie ma sobie równych. Bądź $gwdzięczny:wdzięczna;, że nie żąda więcej za wiedzę, którą przekazuje innym. Idź już i odszukaj go na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 'Kunszt, z jakim Telonis wytwarza zbroje, nie ma sobie równych. Bądź $gwdzięczny:wdzięczna;, że nie żąda więcej za wiedzę, którą przekazuje innym. Idź już i odszukaj go na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 0),
(5373, 'plPL', 'My sadzimy warzywa. Nasze warzywa zjada królik. Królika pożera wilk. Wilka zabijamy my. Z truchła wilka bierzemy mięso i skórę. To ten cały Magiczny Krąg Życia, czy jak to się tam nazywa.\nA teraz idź do Telonisa w Enklawie Cenariona, żeby zacząć naukę, i pozwól mi wrócić do obowiązków.', 'My sadzimy warzywa. Nasze warzywa zjada królik. Królika pożera wilk. Wilka zabijamy my. Z truchła wilka bierzemy mięso i skórę. To ten cały Magiczny Krąg Życia, czy jak to się tam nazywa.\nA teraz idź do Telonisa w Enklawie Cenariona, żeby zacząć naukę, i pozwól mi wrócić do obowiązków.', 0),
(5377, 'plPL', 'Zwierzęta tego świata, umierając, dają nam zarówno życie, jak i ochronę. Jeśli czujesz, że potrafisz okazać należny szacunek ich ofierze, zawód skórnika może ci odpowiadać. Porozmawiaj z Eladriel na Tarasie Rzemieślników w północnej części Darnassus, by dowiedzieć się więcej.', 'Zwierzęta tego świata, umierając, dają nam zarówno życie, jak i ochronę. Jeśli czujesz, że potrafisz okazać należny szacunek ich ofierze, zawód skórnika może ci odpowiadać. Porozmawiaj z Eladriel na Tarasie Rzemieślników w północnej części Darnassus, by dowiedzieć się więcej.', 0),
(5381, 'plPL', 'Jeśli masz choć cień nadziei, że nauczysz się krawiectwa, z pewnością szukasz Me\'Lynn. Mieszka na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 'Jeśli masz choć cień nadziei, że nauczysz się krawiectwa, z pewnością szukasz Me\'Lynn. Mieszka na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 0),
(5470, 'plPL', 'Zbieranie ziół i wiedza o nich to specjalność Firodrena Wzywającego Księżyc. Szukaj go w Ogrodach Świątynnych w południowo-zachodniej części Darnassus.', 'Zbieranie ziół i wiedza o nich to specjalność Firodrena Wzywającego Księżyc. Szukaj go w Ogrodach Świątynnych w południowo-zachodniej części Darnassus.', 0),
(5471, 'plPL', 'Rośnie nam tu $gmłody zielarz:młoda zielarka;? W takim razie odwiedź Firodrena Wzywającego Księżyc w Ogrodach Świątynnych. Może zdradzi ci kilka sztuczek swojego fachu.', 'Rośnie nam tu $gmłody zielarz:młoda zielarka;? W takim razie odwiedź Firodrena Wzywającego Księżyc w Ogrodach Świątynnych. Może zdradzi ci kilka sztuczek swojego fachu.', 0),
(5615, 'plPL', 'Pochlebiasz mi, ale naprawdę nie jestem zainteresowana... Co? Chcesz wiedzieć, gdzie nauczyć się zaklinania? Och, ale wstyd! No cóż, $gpowinieneś:powinnaś;... Na pewno $gmógłbyś:mogłabyś;... iść do, hm... Taladana! Tak, idź do Taladana na Tarasie Rzemieślników!', 'Pochlebiasz mi, ale naprawdę nie jestem zainteresowana... Co? Chcesz wiedzieć, gdzie nauczyć się zaklinania? Och, ale wstyd! No cóż, $gpowinieneś:powinnaś;... Na pewno $gmógłbyś:mogłabyś;... iść do, hm... Taladana! Tak, idź do Taladana na Tarasie Rzemieślników!', 0),
(6068, 'plPL', 'Druidami, zawsze czujnymi w obronie świata natury, kieruje arcydruid Fandral Jeleniorogi, który przebywa w Enklawie Cenariona. Znajdziesz go wraz z innymi nauczycielami druidów w północnej części Darnassus.', 'Druidami, zawsze czujnymi w obronie świata natury, kieruje arcydruid Fandral Jeleniorogi, który przebywa w Enklawie Cenariona. Znajdziesz go wraz z innymi nauczycielami druidów w północnej części Darnassus.', 0),
(6353, 'plPL', 'Alchemik? Żaden kłopot. Ainethil dzięki swojej pracy i trudom stała się najbieglejszą alchemiczką na Tarasie Rzemieślników. Na twoim miejscu pobiegłabym tam co sił w nogach. Co sił w nogach! No, zmykaj!', 'Alchemik? Żaden kłopot. Ainethil dzięki swojej pracy i trudom stała się najbieglejszą alchemiczką na Tarasie Rzemieślników. Na twoim miejscu pobiegłabym tam co sił w nogach. Co sił w nogach! No, zmykaj!', 0),
(6354, 'plPL', '$GKolejny materialista:Kolejna materialistka;, co? Cóż, jeśli masz obsesję na punkcie swoich cennych przedmiotów, pewnie zechcesz je przechować w banku Darnassus, w centrum naszego miasta.', '$GKolejny materialista:Kolejna materialistka;, co? Cóż, jeśli masz obsesję na punkcie swoich cennych przedmiotów, pewnie zechcesz je przechować w banku Darnassus, w centrum naszego miasta.', 0),
(6355, 'plPL', 'Przez wieki spędzone na łowieniu ryb Astaia wyłowiła kilka ciekawych skarbów. Może odwiedzisz ją na Tarasie Kupców i poprosisz, żeby ci je pokazała?', 'Przez wieki spędzone na łowieniu ryb Astaia wyłowiła kilka ciekawych skarbów. Może odwiedzisz ją na Tarasie Kupców i poprosisz, żeby ci je pokazała?', 0),
(6356, 'plPL', 'Lysheana zaopatrzy cię w odpowiednie dokumenty. Mieszka na Tarasie Rzemieślników w północno-wschodniej części Darnassus. Niech twoje bractwo przysporzy chwały nocnym elfom!', 'Lysheana zaopatrzy cię w odpowiednie dokumenty. Mieszka na Tarasie Rzemieślników w północno-wschodniej części Darnassus. Niech twoje bractwo przysporzy chwały nocnym elfom!', 0),
(6357, 'plPL', 'Szukasz Vesprystusa. Pieczę sprawuje nad hipogryfami, które przylatują do podnóża Teldrassilu i odlatują stamtąd. Dotrzesz do niego przez portal w zachodniej części Darnassus, który zaprowadzi cię do Wioski Rut\'theran.', 'Szukasz Vesprystusa. Pieczę sprawuje nad hipogryfami, które przylatują do podnóża Teldrassilu i odlatują stamtąd. Dotrzesz do niego przez portal w zachodniej części Darnassus, który zaprowadzi cię do Wioski Rut\'theran.', 0),
(6358, 'plPL', 'Jocaste była w swoich czasach największą z łowczyń. Dziś znajdziesz ją w Enklawie Cenariona, gdzie uczy tych, którzy dopiero wkraczają na ścieżkę łowcy.', 'Jocaste była w swoich czasach największą z łowczyń. Dziś znajdziesz ją w Enklawie Cenariona, gdzie uczy tych, którzy dopiero wkraczają na ścieżkę łowcy.', 0),
(6359, 'plPL', 'Czyżby słońce już wzeszło? Noc zawsze jest za krótka! No cóż, Saelienne dobrze się tobą zajmie. Znajdziesz ją, jak dogląda gości, na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 'Czyżby słońce już wzeszło? Noc zawsze jest za krótka! No cóż, Saelienne dobrze się tobą zajmie. Znajdziesz ją, jak dogląda gości, na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 0),
(6360, 'plPL', 'Skrzynka pocztowa? Masz list do wysłania, a może jakiś $gdostałeś:dostałaś;? Mam nadzieję, że to coś dobrego! Skrzynka stoi tuż przed bankiem w centrum Darnassus.', 'Skrzynka pocztowa? Masz list do wysłania, a może jakiś $gdostałeś:dostałaś;? Mam nadzieję, że to coś dobrego! Skrzynka stoi tuż przed bankiem w centrum Darnassus.', 0),
(6361, 'plPL', 'Nasza kultura każe nie marnować niczego. Gdy musimy zabić stworzenie, bierzemy z niego, ile się da, by jego ofiara nie poszła na marne.\nJeśli chcesz się nauczyć, jak właściwie zdejmować skórę z upolowanego zwierzęcia, odszukaj Eladriel na Tarasie Rzemieślników.', 'Nasza kultura każe nie marnować niczego. Gdy musimy zabić stworzenie, bierzemy z niego, ile się da, by jego ofiara nie poszła na marne.\nJeśli chcesz się nauczyć, jak właściwie zdejmować skórę z upolowanego zwierzęcia, odszukaj Eladriel na Tarasie Rzemieślników.', 0),
(6362, 'plPL', 'Patrząc na szaty, które szyje Me\'Lynn, można by pomyśleć, że jej igłę pobłogosławiła sama Elune. Jeśli twoja igła nie dostąpiła takiego błogosławieństwa, lepiej ją odwiedź i posłuchaj jej nauk. Znajdziesz ją na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 'Patrząc na szaty, które szyje Me\'Lynn, można by pomyśleć, że jej igłę pobłogosławiła sama Elune. Jeśli twoja igła nie dostąpiła takiego błogosławieństwa, lepiej ją odwiedź i posłuchaj jej nauk. Znajdziesz ją na Tarasie Rzemieślników w północno-wschodniej części Darnassus.', 0),
(6363, 'plPL', 'Sildinair wyszkoliła wiele Strażniczek, które strzegą naszego ukochanego miasta. Jestem pewna, że nawet z kogoś takiego jak ty zrobi wojownika. Szukaj jej na Tarasie Wojowników, przy wejściu do miasta.', 'Sildinair wyszkoliła wiele Strażniczek, które strzegą naszego ukochanego miasta. Jestem pewna, że nawet z kogoś takiego jak ty zrobi wojownika. Szukaj jej na Tarasie Wojowników, przy wejściu do miasta.', 0),
(6365, 'plPL', 'Jeden został otwarty na Tarasie Kupców. Jeśli pójdziesz ścieżką prowadzącą od banku na południowy wschód, łatwo go znajdziesz.', 'Jeden został otwarty na Tarasie Kupców. Jeśli pójdziesz ścieżką prowadzącą od banku na południowy wschód, łatwo go znajdziesz.', 0),
(6366, 'plPL', 'Ach, ta wszechobecna obsesja na punkcie bogactwa. Cóż, los ci sprzyja – dom aukcyjny znajdziesz na Tarasie Kupców.', 'Ach, ta wszechobecna obsesja na punkcie bogactwa. Cóż, los ci sprzyja – dom aukcyjny znajdziesz na Tarasie Kupców.', 0),
(6400, 'plPL', '', 'Cześć! Właśnie wróciłam z wyprawy do Ruin Kel\'Theril na południowym zachodzie. Teraz zamierzam zbadać dziczołaki, które żyją tuż wyżej na grani, w Gąszczu Sowiego Skrzydła.$B$BCzy $grozmawiałeś:rozmawiałaś; z Erelasem Bursztynowym Niebem w Wiosce Rut\'theran? To on poprosił mnie, żebym tu przyszła – może i dla ciebie ma jakieś zadanie.', 0),
(7067, 'plPL', 'Bank znajduje się w spokojnym mieście Darnassus. Musisz się tam udać, jeśli chcesz przechować swój dobytek.', 'Bank znajduje się w spokojnym mieście Darnassus. Musisz się tam udać, jeśli chcesz przechować swój dobytek.', 0),
(7068, 'plPL', 'Jeśli szukasz banku, twoja droga wiedzie do serca Darnassus. Tam przechowasz swoje skarby.', 'Jeśli szukasz banku, twoja droga wiedzie do serca Darnassus. Tam przechowasz swoje skarby.', 0),
(7069, 'plPL', 'Prom z Rut\'theran', 'Prom z Rut\'theran', 0),
(7070, 'plPL', 'Aby dotrzeć do promu z Rut\'theran, musisz udać się do Darnassus i przejść przez portal do Wioski Rut\'theran u podnóża Teldrassilu.', 'Aby dotrzeć do promu z Rut\'theran, musisz udać się do Darnassus i przejść przez portal do Wioski Rut\'theran u podnóża Teldrassilu.', 0),
(7073, 'plPL', 'Sprawy tak urzędowej natury załatwia się wyłącznie w Darnassus. Musisz się tam udać, aby rozpocząć zakładanie swojej gildii.', 'Sprawy tak urzędowej natury załatwia się wyłącznie w Darnassus. Musisz się tam udać, aby rozpocząć zakładanie swojej gildii.', 0),
(7074, 'plPL', 'Dokumenty takie jak papiery założycielskie gildii można otrzymać od mistrzyni gildii w Darnassus.', 'Dokumenty takie jak papiery założycielskie gildii można otrzymać od mistrzyni gildii w Darnassus.', 0),
(7076, 'plPL', 'W łóżkach, o które dba karczmarz Keldamyr w karczmie w Dolanaar, z pewnością spokojnie się wyśpisz.', 'W łóżkach, o które dba karczmarz Keldamyr w karczmie w Dolanaar, z pewnością spokojnie się wyśpisz.', 0),
(7077, 'plPL', 'Jeśli potrzebujesz czasu, by odpocząć i odzyskać siły, najlepsze warunki znajdziesz w karczmie w Dolanaar. Karczmarz Keldamyr dopilnuje, by niczego ci nie brakowało.', 'Jeśli potrzebujesz czasu, by odpocząć i odzyskać siły, najlepsze warunki znajdziesz w karczmie w Dolanaar. Karczmarz Keldamyr dopilnuje, by niczego ci nie brakowało.', 0),
(7079, 'plPL', 'W okolicach Dolanaar znajdziesz wielu nauczycieli, którzy mają za sobą całe wieki doświadczenia i mogą cię szkolić. Do kogo mam cię skierować?', 'W okolicach Dolanaar znajdziesz wielu nauczycieli, którzy mają za sobą całe wieki doświadczenia i mogą cię szkolić. Do kogo mam cię skierować?', 0),
(7081, 'plPL', 'Szukasz pomocy druida? Idź więc do Kala, przy księżycowej studni tuż na południe od karczmy w Dolanaar.', 'Szukasz pomocy druida? Idź więc do Kala, przy księżycowej studni tuż na południe od karczmy w Dolanaar.', 0),
(7082, 'plPL', 'Druid Kal często przebywa przy księżycowej studni w Dolanaar. Jestem pewna, że zapewni ci szkolenie, którego potrzebujesz.', 'Druid Kal często przebywa przy księżycowej studni w Dolanaar. Jestem pewna, że zapewni ci szkolenie, którego potrzebujesz.', 0),
(7084, 'plPL', 'Jeśli szukasz łowcy, $gpowinieneś:powinnaś; odwiedzić Dazalara. Zwykle znajdziesz go tuż przed karczmą w Dolanaar.', 'Jeśli szukasz łowcy, $gpowinieneś:powinnaś; odwiedzić Dazalara. Zwykle znajdziesz go tuż przed karczmą w Dolanaar.', 0),
(7085, 'plPL', 'Dazalar słynie w Dolanaar ze swoich łowieckich umiejętności. Może porozmawiasz z nim i sprawdzisz, czego może cię nauczyć?', 'Dazalar słynie w Dolanaar ze swoich łowieckich umiejętności. Może porozmawiasz z nim i sprawdzisz, czego może cię nauczyć?', 0),
(7087, 'plPL', 'W Dolanaar mieszka kapłanka imieniem Laurna Poranne Światło. Zdaje się, że znajdziesz ją tuż na północ od karczmy.', 'W Dolanaar mieszka kapłanka imieniem Laurna Poranne Światło. Zdaje się, że znajdziesz ją tuż na północ od karczmy.', 0),
(7088, 'plPL', 'Laurna Poranne Światło leczy mieszkańców okolic Dolanaar. Może zdoła cię nauczyć dróg kapłana.', 'Laurna Poranne Światło leczy mieszkańców okolic Dolanaar. Może zdoła cię nauczyć dróg kapłana.', 0),
(7090, 'plPL', 'Łotr? Nie mam zwyczaju polecać takich typów, ale zdaje się, że szukasz Jannoka. Znajdziesz go w karczmie w Dolanaar.', 'Łotr? Nie mam zwyczaju polecać takich typów, ale zdaje się, że szukasz Jannoka. Znajdziesz go w karczmie w Dolanaar.', 0),
(7091, 'plPL', 'Szukasz łotra? Zdaje się, że Jannok pasuje do tego opisu. Może porozmawiasz z nim w karczmie w Dolanaar?', 'Szukasz łotra? Zdaje się, że Jannok pasuje do tego opisu. Może porozmawiasz z nim w karczmie w Dolanaar?', 0),
(7093, 'plPL', 'Kyra Wietrzne Ostrze włada swoim ostrzem z wielką wprawą. Z pewnością może cię czegoś nauczyć. Znajdziesz ją w karczmie w Dolanaar.', 'Kyra Wietrzne Ostrze włada swoim ostrzem z wielką wprawą. Z pewnością może cię czegoś nauczyć. Znajdziesz ją w karczmie w Dolanaar.', 0),
(7094, 'plPL', 'Miałam kiedyś przyjemność widzieć Kyrę Wietrzne Ostrze w walce. Po tym, co zobaczyłam, jestem pewna, że dobrze cię wyszkoli. Szukaj jej w karczmie w Dolanaar.', 'Miałam kiedyś przyjemność widzieć Kyrę Wietrzne Ostrze w walce. Po tym, co zobaczyłam, jestem pewna, że dobrze cię wyszkoli. Szukaj jej w karczmie w Dolanaar.', 0),
(7096, 'plPL', 'Droga tych, którzy obierają zawód, jest długa, lecz daje wiele satysfakcji. Którą ścieżką chcesz podążać?', 'Droga tych, którzy obierają zawód, jest długa, lecz daje wiele satysfakcji. Którą ścieżką chcesz podążać?', 0),
(7098, 'plPL', 'Cyndra nie musuje tak jak jej mikstury, ale jej łagodny sposób bycia sprzyja nauczaniu fachu. Znajdziesz ją tuż na wschód od karczmy w Dolanaar.', 'Cyndra nie musuje tak jak jej mikstury, ale jej łagodny sposób bycia sprzyja nauczaniu fachu. Znajdziesz ją tuż na wschód od karczmy w Dolanaar.', 0),
(7099, 'plPL', 'Wiedza Cyndry o alchemii jest dość ograniczona, ale na początek z pewnością wystarczy. Uprawia swoje rzemiosło tuż na wschód od karczmy w Dolanaar.', 'Wiedza Cyndry o alchemii jest dość ograniczona, ale na początek z pewnością wystarczy. Uprawia swoje rzemiosło tuż na wschód od karczmy w Dolanaar.', 0),
(7101, 'plPL', 'Zdaje się, że Zarrin dobrze zna się na gotowaniu. Może sprawdzisz, czy pokaże ci kilka przepisów? Zwykle gotuje przy karczmie w Dolanaar.', 'Zdaje się, że Zarrin dobrze zna się na gotowaniu. Może sprawdzisz, czy pokaże ci kilka przepisów? Zwykle gotuje przy karczmie w Dolanaar.', 0),
(7102, 'plPL', 'W Dolanaar przydałby się jeszcze jeden kucharz – nie żeby kuchni Zarrina czegoś brakowało, rzecz jasna. Może sprawdzisz, czego może cię nauczyć?', 'W Dolanaar przydałby się jeszcze jeden kucharz – nie żeby kuchni Zarrina czegoś brakowało, rzecz jasna. Może sprawdzisz, czego może cię nauczyć?', 0),
(7104, 'plPL', 'Alanna Krucze Oko przypisuje część swojego talentu do zaklinania obcowaniu z duchami na Polanie Wyroczni. Teraz też powinna tam być.', 'Alanna Krucze Oko przypisuje część swojego talentu do zaklinania obcowaniu z duchami na Polanie Wyroczni. Teraz też powinna tam być.', 0),
(7105, 'plPL', 'Alanna spędza większość dnia na Polanie Wyroczni, gdzie uprawia swój zawód. Jeśli chcesz nauczyć się fachu zaklinacza, musisz się tam udać, żeby ją znaleźć.', 'Alanna spędza większość dnia na Polanie Wyroczni, gdzie uprawia swój zawód. Jeśli chcesz nauczyć się fachu zaklinacza, musisz się tam udać, żeby ją znaleźć.', 0),
(7107, 'plPL', 'Byancie często pomagała Strażniczkom, które patrolują okoliczne dzikie ostępy. Porozmawiaj z nią, jeśli chcesz się nauczyć pierwszej pomocy.', 'Byancie często pomagała Strażniczkom, które patrolują okoliczne dzikie ostępy. Porozmawiaj z nią, jeśli chcesz się nauczyć pierwszej pomocy.', 0),
(7108, 'plPL', 'Umiejętności Byancie w pierwszej pomocy nieraz okazały się przydatne. Jeśli chcesz się od niej uczyć, znajdziesz ją tuż na północ od karczmy w Dolanaar.', 'Umiejętności Byancie w pierwszej pomocy nieraz okazały się przydatne. Jeśli chcesz się od niej uczyć, znajdziesz ją tuż na północ od karczmy w Dolanaar.', 0),
(7110, 'plPL', 'Po ostatnich napaściach w okolicach Jeziora Al\'Ameth wszyscy rybacy przenieśli się do Darnassus. Tam poszukaj kogoś, kto cię wyszkoli.', 'Po ostatnich napaściach w okolicach Jeziora Al\'Ameth wszyscy rybacy przenieśli się do Darnassus. Tam poszukaj kogoś, kto cię wyszkoli.', 0),
(7111, 'plPL', 'Przez drzewczyki rybakom zrobiło się zbyt trudno cokolwiek złowić w okolicach Dolanaar. Lepiej poszukaj nauczyciela w Darnassus.', 'Przez drzewczyki rybakom zrobiło się zbyt trudno cokolwiek złowić w okolicach Dolanaar. Lepiej poszukaj nauczyciela w Darnassus.', 0),
(7113, 'plPL', 'Malorne jakimś cudem potrafi zbierać najdelikatniejsze zioła, nie uszkadzając ich. To od niego z pewnością $gpowinieneś:powinnaś; się uczyć. Mieszka tuż na wschód od karczmy w Dolanaar.', 'Malorne jakimś cudem potrafi zbierać najdelikatniejsze zioła, nie uszkadzając ich. To od niego z pewnością $gpowinieneś:powinnaś; się uczyć. Mieszka tuż na wschód od karczmy w Dolanaar.', 0),
(7114, 'plPL', 'Ziołozbieractwo wymaga delikatnego dotyku, którego mało kto potrafi nauczyć tak jak Malorne. Szukaj go na wschód od karczmy w Dolanaar.', 'Ziołozbieractwo wymaga delikatnego dotyku, którego mało kto potrafi nauczyć tak jak Malorne. Szukaj go na wschód od karczmy w Dolanaar.', 0),
(7116, 'plPL', 'Tkacze Grzyw uprawiają swoje zawody w domu przy drodze do Darnassus. Nadyia jest świetną nauczycielką garbarstwa. Sprawdź, czego może cię nauczyć.', 'Tkacze Grzyw uprawiają swoje zawody w domu przy drodze do Darnassus. Nadyia jest świetną nauczycielką garbarstwa. Sprawdź, czego może cię nauczyć.', 0),
(7117, 'plPL', 'Przez lata praktyki Nadyia stała się doskonałą garbarką. Udaj się na zachód drogą do Darnassus, by ją odwiedzić – może podzieli się z tobą częścią swojej wiedzy.', 'Przez lata praktyki Nadyia stała się doskonałą garbarką. Udaj się na zachód drogą do Darnassus, by ją odwiedzić – może podzieli się z tobą częścią swojej wiedzy.', 0),
(7120, 'plPL', 'Radnaal uprawia swoje rzemiosło przed domem przy drodze do Darnassus. Zajrzyj do niego i sprawdź, czego może cię nauczyć.', 'Radnaal uprawia swoje rzemiosło przed domem przy drodze do Darnassus. Zajrzyj do niego i sprawdź, czego może cię nauczyć.', 0),
(7122, 'plPL', 'Jestem pewna, że w Darnassus znajdzie się krawiec, który mógłby cię wyszkolić. Gdy tam dotrzesz, zapytaj którąś ze Strażniczek w Darnassus o krawca.', 'Jestem pewna, że w Darnassus znajdzie się krawiec, który mógłby cię wyszkolić. Gdy tam dotrzesz, zapytaj którąś ze Strażniczek w Darnassus o krawca.', 0),
(7123, 'plPL', 'Wiele materiałów, których potrzebują krawcy, przychodzi przez Darnassus. Nic dziwnego, że wszyscy przenieśli się tam do pracy. Jeśli chcesz zostać krawcem, lepiej udaj się do Darnassus.', 'Wiele materiałów, których potrzebują krawcy, przychodzi przez Darnassus. Nic dziwnego, że wszyscy przenieśli się tam do pracy. Jeśli chcesz zostać krawcem, lepiej udaj się do Darnassus.', 0),
(7245, 'plPL', 'Przez tysiąclecia Ilyenia Księżycowy Ogień opanowała wiele rodzajów broni, a teraz uczy innych, jak się nimi posługiwać. Jeśli chcesz się szkolić, znajdziesz ją na Tarasie Wojowników.', 'Przez tysiąclecia Ilyenia Księżycowy Ogień opanowała wiele rodzajów broni, a teraz uczy innych, jak się nimi posługiwać. Jeśli chcesz się szkolić, znajdziesz ją na Tarasie Wojowników.', 0),
(7246, 'plPL', 'Większość szkolenia w walce bronią odebrałam u Ilyenii Księżycowy Ogień na Tarasie Wojowników. Dobrze zrobisz, jeśli ją odszukasz, gdy zechcesz nauczyć się posługiwania nową bronią.', 'Większość szkolenia w walce bronią odebrałam u Ilyenii Księżycowy Ogień na Tarasie Wojowników. Dobrze zrobisz, jeśli ją odszukasz, gdy zechcesz nauczyć się posługiwania nową bronią.', 0),
(7365, 'plPL', '', 'Pamiętaj, potrzebuję twojej pomocy, by właściwie skupić moc. Po drodze kilka razy poproszę cię o wsparcie, więc bądź $ggotów:gotowa;.', 0),
(7375, 'plPL', '', 'To niebieskie światło... Dziwne. Jak myślisz, co ono oznacza?', 0),
(7378, 'plPL', '', 'Proszę, zapal to, gdy będę skupiać moc.', 0),
(7379, 'plPL', '', 'To tutaj. Zapalmy go.', 0),
(7380, 'plPL', '', 'Znaleźliśmy!', 0),
(7385, 'plPL', '', 'Czas na ostatni krok – musimy uruchomić ołtarz.', 0),
(7386, 'plPL', '', 'Odczytam słowa wyryte w kamieniu, a ty musisz znaleźć sposób, by rozpalić tu ogień.', 0),
(7388, 'plPL', '', 'Co się dzieje? Spójrz!', 0),
(7391, 'plPL', '', 'Kapłanki, prosimy, wybaczcie nam to najście. Nie chcemy tu nikogo skrzywdzić.', 0),
(7392, 'plPL', '', 'Chcemy tylko wiedzieć, dlaczego dziczołaki strzegą tego miejsca...', 0),
(7410, 'plPL', '', 'Znajdźmy następny.', 0),
(7411, 'plPL', '', 'Musimy iść dalej.', 0),
(7412, 'plPL', '', 'Ołtarz jaśnieje! Udało się!', 0),
(7434, 'plPL', '', 'Dziękuję za pomoc, $n. Powodzenia w twoich przygodach.', 0),
(7435, 'plPL', '', 'Chcę tu zostać i zastanowić się nad tym, co zobaczyliśmy. Idź, proszę, do Erelasa i powiedz mu, czego się dowiedzieliśmy.', 0),
(7457, 'plPL', 'Nasz mistrz Malfurion powrócił ze Snu, $N. Jest dla nas światłem latarni, która wskazuje drogę, i musimy zrobić wszystko, co w naszej mocy, by to światło ocalić.', 'Nasz mistrz Malfurion powrócił ze Snu, $N. Jest dla nas światłem latarni, która wskazuje drogę, i musimy zrobić wszystko, co w naszej mocy, by to światło ocalić.', 0),
(7466, 'plPL', '', 'Szykuję się do wyprawy w górę grani, $n. Przydałaby mi się pomoc – pójdziesz ze mną?', 0),
(7467, 'plPL', '', '%s zaczyna intonować dziwne zaklęcie...', 0),
(7588, 'plPL', 'Ach, piękno Cienistego Jaru nigdy nie przestaje cieszyć moich zmysłów!', '', 0),
(7686, 'plPL', '', 'Druidzi mówią, że to tylko kwestia czasu, aż sama natura przegna Hordę z Kalimdoru. A jednak skażenie wciąż szerzy się na naszych ziemiach, nawet tu, na Teldrassilu.', 0),
(7687, 'plPL', '', 'Dobra robota! Coraz lepiej rozumiesz mikstury.', 0),
(7780, 'plPL', '', 'Dziękuję! Dziękuję, $gkapłanie:kapłanko;. Teraz, z mocą Eluny za plecami, mogę stawić czoła tym skażonym drzewczykom!', 0),
(7781, 'plPL', '', 'Żegnaj, i niech Elune zawsze będzie z tobą.', 0),
(7877, 'plPL', '', 'Elune ma wiele tajemnic, ale nie wolno ich zdradzać byle komu.', 0),
(7954, 'plPL', '', 'Musisz robić mniejsze ściegi, $n. Mniej rzeczy wypadnie ci wtedy z kołczanów i ładownic. Poza tym nikt nie lubi tuniki w grudach.', 0),
(8099, 'plPL', 'Aby utrzymać łączność z lądem, nasze hipogryfy bez przerwy latają między Wioską Rut\'theran a Mrocznym Wybrzeżem.', '', 0),
(8100, 'plPL', '', 'Ryby u wybrzeży Teldrassilu są wyjątkowo duże i silne. Podobno to zasługa szybkiego wzrostu naszego nowego drzewa świata.', 0),
(8101, 'plPL', 'Choć u Mrocznego Wybrzeża jest groźniej niż u brzegów Teldrassilu, wielu rybaków znajduje tu zarobek.', '', 0),
(8102, 'plPL', 'To dla mnie zaszczyt zaopatrywać poszukiwaczy przygód, bo to przyszli bohaterowie.', '', 0),
(8323, 'plPL', 'Witaj, $gbracie:siostro;. Jeśli przybywasz na szkolenie, z radością cię wyszkolę.$B$BJesteśmy strażnikami równowagi, teraz i na zawsze, gdy Malfurion spoczywa we Śnie. Nigdy o tym nie zapominaj.', 'Witaj, $gbracie:siostro;. Jeśli przybywasz na szkolenie, z radością cię wyszkolę.$B$BJesteśmy strażnikami równowagi, teraz i na zawsze, gdy Malfurion spoczywa we Śnie. Nigdy o tym nie zapominaj.', 0),
(8526, 'plPL', 'Możesz spokojnie powierzyć swoje zwierzęta opiece Alassina. Przebywa w Enklawie Cenariona, gdzie gromadzą się łowcy.', 'Możesz spokojnie powierzyć swoje zwierzęta opiece Alassina. Przebywa w Enklawie Cenariona, gdzie gromadzą się łowcy.', 0),
(8527, 'plPL', 'Od wielu setek lat Alassin opiekuje się zwierzętami, z którymi zaprzyjaźniają się nasi łowcy. Tutejsi łowcy bardzo cenią sobie jego opiekę. Jeśli ty też go szukasz, znajdziesz go w Enklawie Cenariona.', 'Od wielu setek lat Alassin opiekuje się zwierzętami, z którymi zaprzyjaźniają się nasi łowcy. Tutejsi łowcy bardzo cenią sobie jego opiekę. Jeśli ty też go szukasz, znajdziesz go w Enklawie Cenariona.', 0),
(8530, 'plPL', 'Ach, łagodna Seriadne. Pod jej opieką każde zwierzę jest bezpieczne. Znajdziesz ją tuż przed karczmą w Dolanaar.', 'Ach, łagodna Seriadne. Pod jej opieką każde zwierzę jest bezpieczne. Znajdziesz ją tuż przed karczmą w Dolanaar.', 0),
(8531, 'plPL', 'Szukasz kogoś, kto opiekuje się zwierzętami? W takim razie poszukaj Seriadne przed karczmą w Dolanaar. To jej szukasz.', 'Szukasz kogoś, kto opiekuje się zwierzętami? W takim razie poszukaj Seriadne przed karczmą w Dolanaar. To jej szukasz.', 0),
(10866, 'plPL', 'Chodź, $n. Jezioro jest tuż za zakrętem.', '', 0),
(10867, 'plPL', 'Stań przy mnie, $n. Ochronię cię, gdyby coś poszło nie tak.', '', 0),
(10868, 'plPL', 'Malfurionie!', '', 0),
(10870, 'plPL', 'Był spowity koszmarami, Malfurionie. Co się dzieje w Śnie? Co mogło sprowadzić takie okropieństwa?', '', 0),
(10872, 'plPL', 'Tak też przeczuwałem, Malfurionie. Nadciągają mroczne dni.', '', 0),
(10874, 'plPL', 'Zbyt długo cię nie było, Malfurionie. Pokój między dziećmi Azeroth jest w najlepszym razie kruchy. Co z moim ojcem? Z twoim bratem? Masz jakieś wieści?\n', '', 0),
(10877, 'plPL', 'Żegnaj, stary przyjacielu... Żegnaj...', '', 0),
(10879, 'plPL', 'Wracajmy do gaju, $gśmiertelniku:śmiertelniczko;.', '', 0),
(11145, 'plPL', 'Gwiazdy tych czasów obrały nowe ścieżki – są latarniami nadziei i siły dla nadchodzących wieków.', 'Gwiazdy tych czasów obrały nowe ścieżki – są latarniami nadziei i siły dla nadchodzących wieków.', 0),
(11282, 'plPL', 'Dzięki fragmentom, które $gzebrałeś:zebrałaś;, odnajdziemy źródło Koszmaru, $n. Stamtąd przeciągniemy Eranikusa przez szczelinę w Śnie. Przygotuj się, $N. Zapraszamy do naszego świata ucieleśnienie Koszmaru.', '', 0),
(11290, 'plPL', 'Szczelina otworzy się tam, nad Jeziorem Elun\'ara. Przygotuj się, $n. Wkroczeniu Eranikusa do naszego świata będą towarzyszyć chaos i zamęt.\n', '', 0),
(11291, 'plPL', 'Nie cofnie się przed niczym, by dotrzeć do fizycznego ciała Malfuriona. Do tego nie może dojść... Musimy zająć bestię na tyle długo, by zdążyła przybyć Tyrande.', '', 0),
(11292, 'plPL', 'Broń Nocnego Azylu, $gbohaterze:bohaterko;...', '', 0),
(11293, 'plPL', 'Pomiocie! Poczuj potęgę Cenariusa!', '', 0),
(11295, 'plPL', 'Kto tu jest przewidywalny, bestio? Czyżbyś naprawdę myślał, że przywołamy cię prosto na Malfuriona? Nadchodzi twoje odkupienie, Eranikusie. Zostaniesz oczyszczony z tego szaleństwa – z tego skażenia.\n', '', 0),
